    // -- frame sink: THE ONE RULE ------------------------------------------

    /// Recording sink used to prove ordering and to prove the drain loop does
    /// nothing else per frame.
    #[derive(Default)]
    struct RecordingSink {
        accepted: Mutex<Vec<Bytes>>,
    }

    impl FrameSink for RecordingSink {
        fn accept(&self, frame: Bytes) -> FrameSinkOutcome {
            if let Ok(mut g) = self.accepted.lock() {
                g.push(frame);
            }
            FrameSinkOutcome::Captured
        }
    }

    fn wal_dir(name: &str) -> std::path::PathBuf {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        std::env::temp_dir().join(format!("tv-poolsup-{name}-{}-{nanos}", std::process::id()))
    }

    #[test]
    fn test_wal_ring_sink_captures_durably_then_publishes() {
        let dir = wal_dir("capture");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel::<CapturedFrame>(4);
        let sink = WalRingSink::new(
            std::sync::Arc::clone(&spill),
            tx,
            std::sync::Arc::new(RingByteBudget::new(usize::MAX)),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        let frame = Bytes::from_static(&[2u8, 16, 0, 0, 0, 0, 0, 0]);
        assert_eq!(sink.accept(frame.clone()), FrameSinkOutcome::Captured);
        let published = rx.try_recv().expect("a captured frame must be published");
        assert_eq!(published.bytes, frame);
        assert!(
            published.seq > 0,
            "the published frame must carry the sequence minted at the read \
             instant — a zero would mean nothing stamped it"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// R7 (2026-10-01): a sink built the old way may always dial, and an
    /// opted-in sink follows the process's lock-held flag on every read.
    #[test]
    fn with_dial_permit_follows_the_lock_flag_and_defaults_to_permitted() {
        let dir = wal_dir("dial-permit");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        let budget = std::sync::Arc::new(RingByteBudget::new(usize::MAX));
        let (frames_tx, _frames_rx) = tokio::sync::mpsc::channel::<CapturedFrame>(4);
        let build = || {
            WalRingSink::new(
                std::sync::Arc::clone(&spill),
                frames_tx.clone(),
                std::sync::Arc::clone(&budget),
                WsType::LiveFeed,
                DhanEndpointType::MainFeed,
                0,
            )
        };
        assert!(
            build().dial_permitted(),
            "no permit wired = always permitted"
        );
        assert!(
            RecordingSink::default().dial_permitted(),
            "the trait default must permit"
        );

        let held = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let gated = build().with_dial_permit(std::sync::Arc::clone(&held));
        assert!(!gated.dial_permitted(), "lock not held = no dial");
        held.store(true, std::sync::atomic::Ordering::Release);
        assert!(gated.dial_permitted(), "lock held again = dial");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn with_audit_is_silent_until_opted_in_and_names_its_own_endpoint() {
        // Two properties in one test because they are the same property from
        // both sides: a sink built the old way must emit NOTHING (so every
        // existing caller, test and bench is unchanged by construction), and
        // an opted-in sink must report the endpoint it actually serves.
        //
        // The endpoint half is the one with teeth. The sink's `ws_type` field
        // is `LiveFeed` for ALL fifteen market-data sockets — it is the WAL
        // record discriminant, not the socket's identity — so a consumer that
        // built the audit row from it would file a depth-200 park under the
        // main feed and leave the table unable to answer which pool went dark,
        // which is the only question it exists to answer. Carrying the
        // ENDPOINT on the event is what makes that mistake unavailable
        // downstream.
        use tickvault_common::ws_event_types::WsEventKind;

        let dir = wal_dir("lifecycle");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        let budget = std::sync::Arc::new(RingByteBudget::new(usize::MAX));
        let (frames_tx, _frames_rx) = tokio::sync::mpsc::channel::<CapturedFrame>(4);

        let plain = WalRingSink::new(
            std::sync::Arc::clone(&spill),
            frames_tx.clone(),
            std::sync::Arc::clone(&budget),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );
        // No channel attached: the default path must not panic and must not
        // need one.
        plain.on_lifecycle(WsEventKind::Disconnected, "no_channel_attached");

        for endpoint in [
            DhanEndpointType::MainFeed,
            DhanEndpointType::Depth20,
            DhanEndpointType::Depth200,
        ] {
            let (audit_tx, mut audit_rx) = tokio::sync::mpsc::channel::<WsLifecycleEvent>(4);
            let sink = WalRingSink::new(
                std::sync::Arc::clone(&spill),
                frames_tx.clone(),
                std::sync::Arc::clone(&budget),
                // Deliberately the SAME ws_type for every endpoint — that is
                // exactly the real shape, and the reason the row must not be
                // built from this field.
                WsType::LiveFeed,
                endpoint,
                3,
            )
            .with_audit(audit_tx);

            sink.on_lifecycle(WsEventKind::Disconnected, "park_fatal");
            let event = audit_rx
                .try_recv()
                .expect("an opted-in sink must emit the lifecycle event");
            assert_eq!(
                event.endpoint, endpoint,
                "the event must name the ENDPOINT, not the sink's WAL \
                 discriminant — otherwise every socket files under one label \
                 and the audit cannot say which pool went dark"
            );
            assert_eq!(event.kind, WsEventKind::Disconnected);
            assert_eq!(event.connection_index, 3, "the socket's own index");
            assert_eq!(event.reason, "park_fatal");
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn the_supervisor_reports_connect_and_loss_to_the_sink() {
        // A source pin, because the emit points are inside an async loop whose
        // arms need a live socket and a real supervisor to reach. What must
        // never silently disappear is the CALL — the sink's own emit is unit
        // tested above, and a sink nobody tells about a park records nothing
        // while looking wired.
        //
        // CONNECTED is anchored on the subscribe-ack arm on purpose. The
        // 2026-08-12 blackout is the reason: twelve sockets dialed and every
        // one died on the handshake, so a row written at dial time would have
        // recorded twelve connections that never carried a byte.
        let src = include_str!("pool_supervisor.rs");
        let marker = concat!("#[cfg(", "test)]");
        let production = src.split(marker).next().unwrap_or(src);

        let park = production
            // The match ARM, not the enum construction at `on_event`'s return
            // — anchoring on the bare pattern matched that one first and
            // captured the wrong span. A guard that fails for a reason
            // unrelated to what it protects teaches the next reader to delete
            // it, so the anchor has to be the thing itself.
            .split("SupervisorAction::Park { reason } => {")
            .nth(1)
            .and_then(|s| s.split("return ConnectionExit::Parked").next())
            .expect("the park arm must exist");
        assert!(
            park.contains("sink.on_lifecycle"),
            "a park is PERMANENT — nothing re-dials that socket. It must reach \
             the audit, not only a log line and a counter:\n{park}"
        );

        let subscribe = production
            .split("guard.mark_confirmed();")
            .nth(1)
            .and_then(|s| s.split("action = supervisor.on_event").next())
            .expect("the subscribe-ack arm must exist");
        assert!(
            subscribe.contains("sink.on_lifecycle"),
            "CONNECTED must be recorded at subscribe-ack — the first instant \
             the socket can actually deliver:\n{subscribe}"
        );

        let redial_arms = production.matches("guard.mark_lost();").count();
        let audited_redials = production
            .split("guard.mark_lost();")
            .skip(1)
            .filter(|s| {
                s.split("action = supervisor.on_event")
                    .next()
                    .unwrap_or("")
                    .contains("sink.on_lifecycle")
            })
            .count();
        assert_eq!(
            audited_redials, redial_arms,
            "every arm that marks the subscription lost is a real disconnect \
             and must be audited — {audited_redials} of {redial_arms} are"
        );
    }

    #[test]
    fn a_failed_dial_is_audited_with_its_reason() {
        // Same source-pin discipline as the test above, and for the same
        // reason: the emit sits inside an async loop that needs a live socket.
        //
        // Before 2026-08-29 this arm was `Err(_) => ConnEvent::DialFailed` --
        // the error discarded on the spot. The transport had ALREADY
        // classified it into one of five bounded labels and sent it to a
        // counter whose `endpoint` and `reason` labels the EMF processor folds
        // into one summed series per host, so the answer to "which socket, and
        // why" existed for a microsecond and reached no queryable surface. On
        // 2026-08-12 the main feed failed twelve dials with HTTP 400 and the
        // reason is in no table anywhere.
        let src = include_str!("pool_supervisor.rs");
        let marker = concat!("#[cfg(", "test)]");
        let production = src.split(marker).next().unwrap_or(src);

        let dial_arm = production
            .split("SupervisorAction::Dial => {")
            .nth(1)
            .and_then(|s| s.split("SupervisorAction::Subscribe").next())
            .expect("the dial arm must exist");
        assert!(
            dial_arm.contains("WsEventKind::DialFailed"),
            "a failed dial must reach the audit as its own kind:\n{dial_arm}"
        );
        assert!(
            dial_arm.contains("last_dial_failure_reason()"),
            "and it must carry the transport's REASON — a DialFailed row \
             without one answers 'did it fail' and not 'why', which is the \
             half an operator is actually stuck on:\n{dial_arm}"
        );
        // The supervisor must not BRANCH on the reason. Policy stays in the
        // supervisor; this is the audit stamp only.
        assert!(
            !dial_arm.contains("match socket.last_dial_failure_reason"),
            "the reason is for the audit row, never for a decision:\n{dial_arm}"
        );
    }

    #[test]
    fn a_redial_is_audited_with_the_reason_that_caused_it() {
        // Source pin, same discipline as the two tests above.
        //
        // Before 2026-08-29 both redial arms stamped a hardcoded string --
        // "backoff_redial" and "token_refresh_redial" -- so a subscribe
        // failure, an idle-silence teardown, a stale token and a plain
        // transport close all rendered IDENTICALLY in ws_event_audit. The real
        // reason went only to a counter labelled endpoint + reason, and the EMF
        // processor folds label values into one summed series per host. "Why
        // did connection 3 reconnect 210 times today" got the same four words
        // 210 times.
        let src = include_str!("pool_supervisor.rs");
        let marker = concat!("#[cfg(", "test)]");
        let production = src.split(marker).next().unwrap_or(src);

        for arm in [
            "SupervisorAction::SleepThenDial",
            "SupervisorAction::RefreshTokenThenDial",
        ] {
            let body = production
                .split(&format!("{arm} {{ delay_ms }} => {{"))
                .nth(1)
                .and_then(|s| s.split("action = supervisor.on_event").next())
                .unwrap_or_else(|| panic!("the {arm} arm must exist"));
            assert!(
                body.contains("last_redial_reason()"),
                "{arm} must stamp the reason that CAUSED the redial, not a \
                 hardcoded label — the audit row is the only surface that can \
                 tell two causes apart:\n{body}"
            );
        }

        // And the reason must be recorded at the one site every redial passes
        // through, or the row could disagree with the counter beside it.
        let enter = production
            .split("fn enter_backoff(")
            .nth(1)
            .and_then(|s| s.split("\n    fn ").next())
            .expect("enter_backoff must exist");
        assert!(
            enter.contains("self.last_redial_reason = reason;"),
            "enter_backoff is the single choke point every redial reaches:\n{enter}"
        );
    }

    #[test]
    fn every_reconnect_reason_has_a_distinct_audit_label() {
        // The label is what an operator groups by. Two reasons sharing one
        // string would silently merge two different failures into one bucket.
        let labels: Vec<&str> = ReconnectReason::ALL.iter().map(|r| r.as_str()).collect();
        let unique: std::collections::HashSet<&str> = labels.iter().copied().collect();
        assert_eq!(unique.len(), labels.len(), "reason labels must be unique");
        // And none may collide with the two hardcoded strings they replaced,
        // or an old row and a new row would read the same.
        for l in &labels {
            assert_ne!(*l, "backoff_redial");
            assert_ne!(*l, "token_refresh_redial");
        }
    }

    #[test]
    fn the_default_dial_failure_reason_is_honest_about_not_knowing() {
        // A transport that does not classify says "unknown" rather than
        // letting a caller invent a reason it does not have.
        struct Silent;
        impl DhanFeedSocket for Silent {
            async fn connect(&mut self) -> Result<(), SocketFailure> {
                Err(SocketFailure)
            }
            fn write_generation(&self) -> u64 {
                0
            }
            fn send_subscribe(&mut self, _batch: &[SubscribeInstrument]) -> WriteTicket {
                WriteTicket::resolved(0, Err(SocketFailure))
            }
            fn send_ping(&mut self) -> WriteTicket {
                WriteTicket::resolved(0, Err(SocketFailure))
            }
            async fn recv(&mut self) -> SocketEvent {
                SocketEvent::Closed { code: None }
            }
            async fn close<F>(&mut self, _on_frame: F)
            where
                F: FnMut(Bytes) + Send,
            {
            }
        }
        assert_eq!(Silent.last_dial_failure_reason(), "unknown");
    }

    #[test]
    fn test_wal_ring_sink_stamps_receipt_time_in_the_read_task() {
        // The published frame must carry a receipt stamp taken INSIDE
        // `accept` — i.e. on the read task — not left for the drain to
        // invent later. Bracketing the call proves the stamp belongs to the
        // arrival instant and not to whenever a consumer got around to it.
        //
        // Why this matters enough to test: the drain used to call
        // `Utc::now()` itself, so every lag sample measured
        // `Dhan's delivery + our own time queued in the ring`. Under a fold
        // stall the ring backs up and that number inflates — the lag alarm
        // would fire hardest when the fault was LOCAL and name the vendor
        // for it.
        let dir = wal_dir("recvstamp");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel::<CapturedFrame>(4);
        let sink = WalRingSink::new(
            std::sync::Arc::clone(&spill),
            tx,
            std::sync::Arc::new(RingByteBudget::new(usize::MAX)),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        let before = std::time::Instant::now();
        assert_eq!(
            sink.accept(Bytes::from_static(&[2u8, 16, 0, 0, 0, 0, 0, 0])),
            FrameSinkOutcome::Captured
        );
        let after = std::time::Instant::now();

        let published = rx.try_recv().expect("a captured frame must be published");
        assert!(
            published.received_at >= before && published.received_at <= after,
            "the receipt stamp must be taken inside accept() — it fell outside the \
             bracket taken around the call, so it was not stamped at receipt"
        );
        assert!(
            published.wal_backed,
            "a frame the WAL accepted must say so, or the drain stops shedding it"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// 2026-10-02: a frame the WAL REFUSED still reaches the ring
    /// (`CapturedLiveOnly`), and must arrive marked `wal_backed == false` —
    /// otherwise the drain sheds its depth as a "deferral" and lets a busy
    /// rescue drop its rows "to the WAL", neither of which a replay can honour.
    #[test]
    fn test_wal_ring_sink_marks_a_wal_refused_frame_unbacked() {
        let dir = wal_dir("unbacked");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        // A stopped writer refuses every later append: the closest real
        // reproduction of a WAL that cannot take the frame.
        let _ = spill.shutdown(std::time::Duration::from_secs(5));
        let (tx, mut rx) = tokio::sync::mpsc::channel::<CapturedFrame>(4);
        let sink = WalRingSink::new(
            std::sync::Arc::clone(&spill),
            tx,
            std::sync::Arc::new(RingByteBudget::new(usize::MAX)),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        assert_eq!(
            sink.accept(Bytes::from_static(&[2u8, 16, 0, 0, 0, 0, 0, 0])),
            FrameSinkOutcome::CapturedLiveOnly,
            "a WAL refusal must still reach the ring"
        );
        let published = rx.try_recv().expect("the frame must still be published");
        assert!(
            !published.wal_backed,
            "a frame the WAL refused must be marked unbacked"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }
    #[test]
    fn test_wal_ring_sink_stamps_a_distinct_ascending_seq_per_frame() {
        // Two arrivals of BYTE-IDENTICAL content must still receive distinct
        // sequences, or the DEDUP key would collapse them and the second tick
        // would be silently lost. This is the live index-loss class recorded in
        // data-integrity.md (23,146.45 → .75 → .45 on a volume-0 index).
        let dir = wal_dir("seqascend");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel::<CapturedFrame>(4);
        let sink = WalRingSink::new(
            spill,
            tx,
            std::sync::Arc::new(RingByteBudget::new(usize::MAX)),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        let frame = Bytes::from_static(&[2u8, 16, 0, 0, 0, 0, 0, 0]);
        assert_eq!(sink.accept(frame.clone()), FrameSinkOutcome::Captured);
        assert_eq!(sink.accept(frame), FrameSinkOutcome::Captured);

        let first = rx.try_recv().expect("first frame published");
        let second = rx.try_recv().expect("second frame published");
        assert!(
            second.seq > first.seq,
            "identical content must still get a strictly greater sequence: \
             {} then {}",
            first.seq,
            second.seq
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_try_reserve_detailed_refuses_on_slot_cap_when_bytes_are_free() {
        // The dimension that actually bit on 2026-08-28. Bytes wide open,
        // slots exhausted -> refused, and refused as SlotsFull so the two
        // counters stay distinguishable.
        let b = RingByteBudget::with_slot_cap(usize::MAX, 2);
        assert_eq!(b.try_reserve_detailed(1), RingReserve::Granted);
        assert_eq!(b.try_reserve_detailed(1), RingReserve::Granted);
        assert_eq!(
            b.try_reserve_detailed(1),
            RingReserve::SlotsFull,
            "a third frame must be refused on SLOTS even with unlimited bytes"
        );
        assert_eq!(b.slots_resident(), 2);
    }

    #[test]
    fn test_try_reserve_detailed_still_refuses_on_bytes_when_slots_are_free() {
        // The pre-existing dimension must be unchanged by the addition.
        let b = RingByteBudget::with_slot_cap(10, usize::MAX);
        assert_eq!(b.try_reserve_detailed(10), RingReserve::Granted);
        assert_eq!(b.try_reserve_detailed(1), RingReserve::BytesFull);
    }

    #[test]
    fn test_release_slot_returns_the_slot_when_the_byte_reservation_refuses() {
        // Order is slot-then-bytes, so a byte refusal must not leak the slot.
        // Leaking would ratchet the class's slot budget down on every
        // oversized frame until it refused everything -- a slow strangulation
        // that reads as the feed dying for no reason.
        let b = RingByteBudget::with_slot_cap(10, 4);
        assert_eq!(b.try_reserve_detailed(99), RingReserve::BytesFull);
        assert_eq!(b.slots_resident(), 0, "the slot must be returned");
        for _ in 0..4 {
            assert_eq!(b.try_reserve_detailed(1), RingReserve::Granted);
        }
    }

    #[test]
    fn test_release_clears_bytes_and_slots_resident_together() {
        let b = RingByteBudget::with_slot_cap(100, 1);
        assert_eq!(b.try_reserve_detailed(50), RingReserve::Granted);
        assert_eq!(b.try_reserve_detailed(1), RingReserve::SlotsFull);
        b.release(50);
        assert_eq!(b.resident(), 0);
        assert_eq!(b.slots_resident(), 0);
        assert_eq!(b.try_reserve_detailed(50), RingReserve::Granted);
    }

    #[test]
    fn test_with_slot_cap_stops_a_depth_flood_consuming_main_feed_slots() {
        // THE regression this whole change exists to prevent. Two classes
        // sharing one channel: depth exhausts its own share and the main feed
        // is still admitted. Before the slot split, depth could take every
        // slot in the shared pool and main-feed frames were shed -- which is
        // tick loss on the lane that carries the prices.
        let main = RingByteBudget::with_slot_cap(usize::MAX, 3);
        let depth = RingByteBudget::with_slot_cap(usize::MAX, 3);

        for _ in 0..3 {
            assert_eq!(depth.try_reserve_detailed(1), RingReserve::Granted);
        }
        assert_eq!(
            depth.try_reserve_detailed(1),
            RingReserve::SlotsFull,
            "depth must exhaust its OWN share"
        );
        for _ in 0..3 {
            assert_eq!(
                main.try_reserve_detailed(1),
                RingReserve::Granted,
                "the main feed keeps its full share while depth is saturated"
            );
        }
    }

    #[test]
    fn test_new_leaves_slot_cap_unbounded_exactly_as_before() {
        // Every existing caller uses `new`, and none of them should change
        // behaviour. Unbounded slots is exactly what they had before.
        let b = RingByteBudget::new(usize::MAX);
        assert_eq!(b.slot_cap(), usize::MAX);
        for _ in 0..10_000 {
            assert_eq!(b.try_reserve_detailed(1), RingReserve::Granted);
        }
    }

    #[test]
    fn test_wal_ring_sink_full_ring_is_lag_not_capture_loss() {
        // A full ring must NOT stop the reader: stopping costs the pong and
        // turns downstream lag into a disconnect. The frame is already durable.
        let dir = wal_dir("ringfull");
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        let (tx, _rx) = tokio::sync::mpsc::channel::<CapturedFrame>(1);
        let sink = WalRingSink::new(
            spill,
            tx,
            std::sync::Arc::new(RingByteBudget::new(usize::MAX)),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        assert_eq!(
            sink.accept(Bytes::from_static(b"first")),
            FrameSinkOutcome::Captured
        );
        assert_eq!(
            sink.accept(Bytes::from_static(b"second")),
            FrameSinkOutcome::RingFull,
            "a full ring is a lag signal, never silent capture loss"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    // -- ring byte budget ---------------------------------------------------

    #[test]
    fn test_ring_byte_budget_cap_reports_the_configured_ceiling() {
        // `cap()` is what the lane's boot line reports as `ring_max_bytes`.
        // It exists so the operator sees the queue's size in the unit that
        // actually runs out — reporting only the 65,536 frame count is how a
        // 16 GiB ceiling hid behind a number that looks modest.
        let b = RingByteBudget::new(256 * 1024 * 1024);
        assert_eq!(b.cap(), 256 * 1024 * 1024);
        assert_eq!(b.resident(), 0, "a fresh budget holds nothing");
        assert!(b.try_reserve(1_000));
        assert_eq!(
            b.cap(),
            256 * 1024 * 1024,
            "cap is the CEILING and must not move as frames come and go — only \
             resident() tracks occupancy"
        );
    }

    #[test]
    fn test_try_reserve_never_exceeds_the_cap() {
        let b = RingByteBudget::new(100);
        assert!(b.try_reserve(60));
        assert_eq!(b.resident(), 60);
        assert!(b.try_reserve(40), "exactly filling the cap must be allowed");
        assert_eq!(b.resident(), 100);
        assert!(!b.try_reserve(1), "one byte past the cap must be refused");
        assert_eq!(
            b.resident(),
            100,
            "a REFUSED reserve must not move the counter — a fetch_add-then-check \
             would have left the overshoot behind, which is the bound failing to bound"
        );
    }

    #[test]
    fn test_try_reserve_refuses_a_frame_larger_than_the_whole_cap() {
        let b = RingByteBudget::new(1_024);
        assert!(
            !b.try_reserve(4_096),
            "a frame bigger than the entire budget cannot be admitted — admitting it \
             would mean the budget does not bound"
        );
        assert_eq!(b.resident(), 0);
        // And the budget is still usable afterwards: one oversized frame must
        // not poison it for the frames that follow.
        assert!(b.try_reserve(512));
        assert_eq!(b.resident(), 512);
    }

    #[test]
    fn test_ring_byte_budget_release_saturates_and_never_wraps() {
        let b = RingByteBudget::new(1_000);
        assert!(b.try_reserve(100));
        // Over-release: a bookkeeping bug, deliberately made harmless. Wrapping
        // to usize::MAX here would refuse every subsequent frame forever —
        // turning a counting error into a total feed outage.
        b.release(10_000);
        assert_eq!(b.resident(), 0, "release must saturate at zero, not wrap");
        assert!(
            b.try_reserve(1_000),
            "the budget must still admit frames after an over-release"
        );
    }

    #[test]
    fn test_wal_ring_sink_returns_the_reservation_when_the_count_bound_refuses() {
        // The leak this pins: the byte reserve is taken BEFORE `try_send`, so a
        // frame refused by the COUNT bound has a reservation nothing downstream
        // will ever release. Without the release on that path the budget
        // ratchets down on every count-full frame until it refuses everything —
        // a slow strangulation that would present as the feed dying for no
        // visible reason, long after the burst that caused it.
        let dir = std::env::temp_dir().join(format!(
            "tv-ring-budget-leak-{}-{}",
            std::process::id(),
            next_frame_seq()
        ));
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        // Capacity 1: the second frame is refused by COUNT, not by bytes.
        let (tx, _rx) = tokio::sync::mpsc::channel::<CapturedFrame>(1);
        let budget = std::sync::Arc::new(RingByteBudget::new(1_000_000));
        let sink = WalRingSink::new(
            std::sync::Arc::clone(&spill),
            tx,
            std::sync::Arc::clone(&budget),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        assert_eq!(
            sink.accept(Bytes::from_static(b"0123456789")),
            FrameSinkOutcome::Captured
        );
        assert_eq!(budget.resident(), 10);

        for _ in 0..50 {
            assert_eq!(
                sink.accept(Bytes::from_static(b"0123456789")),
                FrameSinkOutcome::RingFull
            );
        }
        assert_eq!(
            budget.resident(),
            10,
            "only the ONE frame actually sitting in the ring may hold a reservation; \
             50 count-refused frames must each have given theirs back"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_wal_ring_sink_refuses_on_the_byte_bound_before_the_count_bound() {
        // The whole point of the second bound: a ring with plenty of SLOTS free
        // still refuses when those slots would hold too many BYTES.
        let dir = std::env::temp_dir().join(format!(
            "tv-ring-budget-bytes-{}-{}",
            std::process::id(),
            next_frame_seq()
        ));
        let spill = std::sync::Arc::new(
            WsFrameSpill::new(&dir).expect("WAL must open under a fresh temp dir"),
        );
        // 64 slots, but only 25 bytes of budget: the count bound cannot bind.
        let (tx, mut rx) = tokio::sync::mpsc::channel::<CapturedFrame>(64);
        let budget = std::sync::Arc::new(RingByteBudget::new(25));
        let sink = WalRingSink::new(
            std::sync::Arc::clone(&spill),
            tx,
            std::sync::Arc::clone(&budget),
            WsType::LiveFeed,
            DhanEndpointType::MainFeed,
            0,
        );

        for _ in 0..2 {
            assert_eq!(
                sink.accept(Bytes::from_static(b"0123456789")),
                FrameSinkOutcome::Captured
            );
        }
        assert_eq!(
            sink.accept(Bytes::from_static(b"0123456789")),
            FrameSinkOutcome::RingFull,
            "20 of 25 bytes are resident and 62 slots are free — the BYTE bound must \
             refuse the third frame, which is the bound the count alone never gave"
        );

        // Draining releases, and the sink accepts again — proving this is
        // backpressure, not a latch.
        let taken = rx.try_recv().expect("a captured frame must be published");
        budget.release(taken.bytes.len());
        assert_eq!(
            sink.accept(Bytes::from_static(b"0123456789")),
            FrameSinkOutcome::Captured,
            "releasing on drain must re-open the budget"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    // -- pool supervisor ----------------------------------------------------

    #[test]
    fn test_pool_supervisor_admits_exactly_the_authorized_sixteen() {
        let now = t0();
        let mut pool = PoolSupervisor::new();
        assert!(pool.is_empty());
        let mut admitted = 0usize;
        for endpoint in DhanEndpointType::ALL {
            for _ in 0..endpoint.max_connections() {
                assert!(pool.admit(endpoint, now).is_ok());
                admitted += 1;
            }
            // The sixth of any five-cap type is refused.
            if endpoint.max_connections() == 5 {
                assert!(pool.admit(endpoint, now).is_err());
            }
        }
        assert_eq!(admitted, 16);
        assert_eq!(pool.len(), 16);
        assert_eq!(pool.total_open(), 16);
        assert_eq!(pool.open_count(DhanEndpointType::MainFeed), 5);
        assert_eq!(pool.open_count(DhanEndpointType::OrderUpdate), 1);
    }

    #[test]
    fn test_pool_supervisor_refuses_the_sixth_main_feed_before_dialing() {
        // Fail-closed: fifteen connections and a loud refusal beats sixteen
        // and a silently murdered pool member.
        let now = t0();
        let mut pool = PoolSupervisor::new();
        for _ in 0..5 {
            assert!(pool.admit(DhanEndpointType::MainFeed, now).is_ok());
        }
        let refusal = pool
            .admit(DhanEndpointType::MainFeed, now)
            .expect_err("the sixth main-feed socket must be refused locally");
        assert_eq!(refusal.endpoint(), DhanEndpointType::MainFeed);
        assert_eq!(pool.len(), 5, "a refusal must register nothing");
    }

    #[test]
    fn test_pool_supervisor_retire_frees_the_budget_slot() {
        let now = t0();
        let mut pool = PoolSupervisor::default();
        let mut slots = Vec::new();
        for _ in 0..5 {
            if let Ok(s) = pool.admit(DhanEndpointType::MainFeed, now) {
                slots.push(s);
            }
        }
        assert!(pool.admit(DhanEndpointType::MainFeed, now).is_err());
        if let Some(&s) = slots.first() {
            pool.retire(s);
        }
        assert_eq!(pool.len(), 4);
        assert!(
            pool.admit(DhanEndpointType::MainFeed, now).is_ok(),
            "retiring a parked connection must return its slot to the budget"
        );
    }

    /// Retiring the same slot twice must NOT hand back two budget entries.
    ///
    /// `retire` used to call `budget.release` unconditionally, even when
    /// `retain` removed nothing. `PoolBudget::release` saturates at zero, so it
    /// cannot underflow and report the problem — it simply undercounts, and the
    /// pool then admits a connection PAST the 5-per-endpoint cap. That cap is
    /// the entire basis of the 16-connection lock.
    ///
    /// It was unreachable only because `retire` has no production caller. A
    /// dormant function that breaks the system's core invariant when called is
    /// worse than one that does nothing: it makes wiring it later a trap.
    #[test]
    fn retiring_the_same_slot_twice_does_not_over_admit_past_the_cap() {
        let now = t0();
        let mut pool = PoolSupervisor::new();
        let mut slots = Vec::new();
        for _ in 0..5 {
            if let Ok(s) = pool.admit(DhanEndpointType::MainFeed, now) {
                slots.push(s);
            }
        }
        assert_eq!(slots.len(), 5, "the cap is 5 main-feed connections");
        assert!(pool.admit(DhanEndpointType::MainFeed, now).is_err());

        let first = *slots.first().expect("five slots were admitted");
        pool.retire(first);
        // The SAME slot again — already gone.
        pool.retire(first);
        assert_eq!(pool.len(), 4, "the second retire removes nothing");

        assert!(
            pool.admit(DhanEndpointType::MainFeed, now).is_ok(),
            "the one genuinely retired slot comes back"
        );
        assert!(
            pool.admit(DhanEndpointType::MainFeed, now).is_err(),
            "and ONLY one — a second admit here means the double-retire handed \
             back a slot that was never occupied, and the 16-connection lock is \
             arithmetic, not a hope"
        );
    }

    /// The same guarantee for a slot the pool never admitted at all.
    #[test]
    fn retiring_an_unknown_slot_does_not_move_the_budget() {
        let now = t0();
        let mut pool = PoolSupervisor::new();
        for _ in 0..5 {
            let _ = pool.admit(DhanEndpointType::MainFeed, now);
        }
        assert!(pool.admit(DhanEndpointType::MainFeed, now).is_err());

        // A slot with a global index the pool has never issued.
        let bogus = ConnectionSlot {
            account: crate::websocket::pool_budget::DhanAccount::Primary,
            endpoint: DhanEndpointType::MainFeed,
            global_index: u8::MAX,
            pool_index: u8::MAX,
        };
        pool.retire(bogus);
        assert_eq!(pool.len(), 5, "nothing was removed");
        assert!(
            pool.admit(DhanEndpointType::MainFeed, now).is_err(),
            "and nothing was released — an unknown slot must never create capacity"
        );
    }
    #[test]
    fn test_pool_supervisor_connection_mut_addresses_by_global_index() {
        let now = t0();
        let mut pool = PoolSupervisor::new();
        let _ = pool.admit(DhanEndpointType::MainFeed, now);
        let _ = pool.admit(DhanEndpointType::Depth200, now);
        let depth_gi = DhanEndpointType::Depth200.jitter_base();
        assert_eq!(
            pool.connection_mut(depth_gi).map(|c| c.slot().endpoint),
            Some(DhanEndpointType::Depth200)
        );
        assert!(pool.connection_mut(200).is_none());
    }

    // -- the async shell ----------------------------------------------------

    #[derive(Default)]
    struct FakeState {
        connect_results: VecDeque<bool>,
        subscribe_results: VecDeque<bool>,
        recv_events: VecDeque<SocketEvent>,
        connects: usize,
        subscribes: usize,
        closes: usize,
        unsubscribe_results: VecDeque<bool>,
        unsubscribes: usize,
        /// Every wire call in order, so a test can assert that the
        /// unsubscribe went out BEFORE the subscribe. On a depth-200 socket
        /// the reverse order asks for two instruments and earns an 804,
        /// so the ORDER is the property under test, not the counts.
        wire_calls: Vec<&'static str>,
        pings: usize,
        /// How long each `send_subscribe` takes on the wire.
        ///
        /// Exists so a test can reach the top-up's wire budget. Under
        /// `start_paused = true` tokio auto-advances, so a "slow" socket costs
        /// no real wall time -- which is the only reason a 40-message top-up
        /// against a 900 ms socket is testable at all.
        subscribe_delay: Option<Duration>,
        /// How long `recv` waits before handing out its next scripted event.
        /// The wait comes BEFORE the pop, so a `recv` cancelled mid-wait (the
        /// top-up pacing gap timing out) consumes nothing — the same
        /// cancel-safety the production read relies on.
        recv_delay: Option<Duration>,
        /// Subscribes and delivered socket events, interleaved in the order
        /// they happened, so a test can see WHEN the reader ran relative to
        /// the writes. Separate from `wire_calls` so the existing wire-order
        /// assertions stay exactly as they were.
        timeline: Vec<&'static str>,
        /// How long each `send_unsubscribe` takes on the wire (plan item
        /// 44f): the write is answered by a spawned task after this long, so
        /// the reader keeps running meanwhile — the production shape.
        unsubscribe_delay: Option<Duration>,
        /// The connection generation `write_generation` reports.
        write_generation: u64,
        /// When set, a DELAYED write bumps `write_generation` just before it
        /// answers — the shape of an answer arriving from a connection that
        /// has since been replaced.
        bump_generation_before_answer: bool,
        /// Frames delivered so far, and — for every delayed write — the
        /// frame count at the instant it answered. The difference between a
        /// write's submit-time and answer-time count is the number of frames
        /// the reader processed DURING that write.
        frames_seen: usize,
        write_answers: Vec<(&'static str, usize)>,
        /// Frame count at each delayed write's SUBMISSION.
        write_submits: Vec<(&'static str, usize)>,
        /// When the script is exhausted, `recv` waits forever instead of
        /// handing out the parking terminator. For tests that exercise a
        /// write path and must not be ended by the reader.
        idle_when_exhausted: bool,
        /// Per scripted event, the subscribe count it waits for before it is
        /// handed out (front pairs with the front of `recv_events`; an event
        /// with no entry is ungated). Since plan item 44f the replay and the
        /// top-up READ the socket during their writes, so a script meant to
        /// arrive "after the replay" must say so instead of relying on the
        /// reader being deaf while it writes.
        recv_after_subscribes: VecDeque<usize>,
        /// The parking terminator is withheld until this many subscribes
        /// have been submitted AND `terminator_not_before` has passed.
        terminator_after_subscribes: usize,
        terminator_not_before: Option<tokio::time::Instant>,
        /// Every security id handed to `send_subscribe`, in order — what the
        /// socket was asked to carry, replay included.
        subscribed_ids: Vec<u64>,
        /// Submits (`kind>`) and answers (`<kind`) of DELAYED writes in the
        /// order they happened, so a test can prove two writes never overlap.
        write_log: Vec<&'static str>,
        /// Frames the next `close` reads during its handshake and hands to
        /// the caller, as the production close does (2026-10-02).
        close_frames: Vec<Bytes>,
        /// Every security id handed to `send_unsubscribe`, in order.
        unsubscribed_ids: Vec<u64>,
        /// `(kind, instruments)` per (un)subscribe message, in order — what
        /// the in-place tests read to prove the 100-per-message split.
        batch_sizes: Vec<(&'static str, usize)>,
    }

    struct FakeSocket {
        state: std::sync::Arc<Mutex<FakeState>>,
    }

    impl DhanFeedSocket for FakeSocket {
        fn connect(
            &mut self,
        ) -> impl std::future::Future<Output = Result<(), SocketFailure>> + Send {
            let state = std::sync::Arc::clone(&self.state);
            async move {
                let ok = match state.lock() {
                    Ok(mut s) => {
                        s.connects += 1;
                        s.connect_results.pop_front().unwrap_or(true)
                    }
                    Err(_) => true,
                };
                if ok { Ok(()) } else { Err(SocketFailure) }
            }
        }

        fn write_generation(&self) -> u64 {
            self.state.lock().map(|s| s.write_generation).unwrap_or(0)
        }

        fn send_unsubscribe(&mut self, batch: &[SubscribeInstrument]) -> WriteTicket {
            let (ok, delay) = match self.state.lock() {
                Ok(mut s) => {
                    s.unsubscribes += 1;
                    s.unsubscribed_ids
                        .extend(batch.iter().map(|i| i.security_id));
                    s.batch_sizes.push(("unsubscribe", batch.len()));
                    s.wire_calls.push("unsubscribe");
                    (
                        s.unsubscribe_results.pop_front().unwrap_or(true),
                        s.unsubscribe_delay,
                    )
                }
                Err(_) => (true, None),
            };
            fake_write(&self.state, "unsubscribe", ok, delay)
        }

        fn send_ping(&mut self) -> WriteTicket {
            let generation = match self.state.lock() {
                Ok(mut s) => {
                    s.pings += 1;
                    s.write_generation
                }
                Err(_) => 0,
            };
            WriteTicket::resolved(generation, Ok(()))
        }

        fn send_subscribe(&mut self, batch: &[SubscribeInstrument]) -> WriteTicket {
            let (ok, delay) = match self.state.lock() {
                Ok(mut s) => {
                    s.subscribes += 1;
                    s.subscribed_ids.extend(batch.iter().map(|i| i.security_id));
                    s.batch_sizes.push(("subscribe", batch.len()));
                    s.wire_calls.push("subscribe");
                    s.timeline.push("subscribe");
                    (
                        s.subscribe_results.pop_front().unwrap_or(true),
                        s.subscribe_delay,
                    )
                }
                Err(_) => (true, None),
            };
            fake_write(&self.state, "subscribe", ok, delay)
        }

        fn recv(&mut self) -> impl std::future::Future<Output = SocketEvent> + Send {
            let state = std::sync::Arc::clone(&self.state);
            async move {
                let delay = state.lock().ok().and_then(|s| s.recv_delay);
                if let Some(d) = delay {
                    tokio::time::sleep(d).await;
                }
                let idle = state
                    .lock()
                    .map(|s| s.recv_events.is_empty() && s.idle_when_exhausted)
                    .unwrap_or(false);
                if idle {
                    std::future::pending::<()>().await;
                }
                // Gates: nothing is popped until the gate opens, so a `recv`
                // cancelled while gated consumes nothing (cancel-safe).
                loop {
                    let (subscribe_gate_open, not_before) = match state.lock() {
                        Ok(s) => {
                            if s.recv_events.is_empty() {
                                (
                                    s.subscribes >= s.terminator_after_subscribes,
                                    s.terminator_not_before,
                                )
                            } else {
                                let gate = s.recv_after_subscribes.front().copied().unwrap_or(0);
                                (s.subscribes >= gate, None)
                            }
                        }
                        Err(_) => (true, None),
                    };
                    if let Some(t) = not_before
                        && tokio::time::Instant::now() < t
                    {
                        tokio::time::sleep_until(t).await;
                        continue;
                    }
                    if subscribe_gate_open {
                        break;
                    }
                    tokio::time::sleep(Duration::from_millis(1)).await;
                }
                match state.lock() {
                    Ok(mut s) => {
                        if !s.recv_events.is_empty() {
                            let _ = s.recv_after_subscribes.pop_front();
                        }
                        let event = s.recv_events.pop_front().unwrap_or(
                            // Terminator: a fatal code parks the loop, so an
                            // exhausted script ends the test instead of hanging.
                            SocketEvent::Closed {
                                code: Some(DisconnectCode::AuthenticationFailed),
                            },
                        );
                        if matches!(event, SocketEvent::Frame(_)) {
                            s.frames_seen += 1;
                        }
                        s.timeline.push(match event {
                            SocketEvent::Frame(_) => "frame",
                            SocketEvent::KeepAlive => "keepalive",
                            SocketEvent::Closed { .. } => "closed",
                        });
                        event
                    }
                    Err(_) => SocketEvent::Closed {
                        code: Some(DisconnectCode::AuthenticationFailed),
                    },
                }
            }
        }

        fn close<F>(&mut self, mut on_frame: F) -> impl std::future::Future<Output = ()> + Send
        where
            F: FnMut(Bytes) + Send,
        {
            let state = std::sync::Arc::clone(&self.state);
            async move {
                let drained = match state.lock() {
                    Ok(mut s) => {
                        s.closes += 1;
                        s.batch_sizes.push(("close", 0));
                        std::mem::take(&mut s.close_frames)
                    }
                    Err(_) => Vec::new(),
                };
                for frame in drained {
                    on_frame(frame);
                }
            }
        }
    }

    fn fake(state: &std::sync::Arc<Mutex<FakeState>>) -> FakeSocket {
        FakeSocket {
            state: std::sync::Arc::clone(state),
        }
    }

    /// Answers one fake write. Without a delay the ticket is answered at
    /// submit time — the old inline behaviour, so every test that never set
    /// a delay is unchanged. With one, a spawned task answers after the delay
    /// while the caller keeps reading: the writer-task shape of production.
    fn fake_write(
        state: &std::sync::Arc<Mutex<FakeState>>,
        kind: &'static str,
        ok: bool,
        delay: Option<Duration>,
    ) -> WriteTicket {
        let outcome = if ok { Ok(()) } else { Err(SocketFailure) };
        let generation = match state.lock() {
            Ok(mut s) => {
                if delay.is_some() {
                    let seen = s.frames_seen;
                    s.write_submits.push((kind, seen));
                    s.write_log.push(match kind {
                        "subscribe" => "subscribe>",
                        _ => "unsubscribe>",
                    });
                }
                s.write_generation
            }
            Err(_) => 0,
        };
        let Some(delay) = delay else {
            return WriteTicket::resolved(generation, outcome);
        };
        let (ticket, reply) = WriteTicket::pending(generation);
        let state = std::sync::Arc::clone(state);
        tokio::spawn(async move {
            tokio::time::sleep(delay).await;
            if let Ok(mut s) = state.lock() {
                if s.bump_generation_before_answer {
                    s.write_generation += 1;
                }
                let seen = s.frames_seen;
                s.write_answers.push((kind, seen));
                s.write_log.push(match kind {
                    "subscribe" => "<subscribe",
                    _ => "<unsubscribe",
                });
            }
            reply.send(outcome);
        });
        ticket
    }

    /// Runs the replay dispatch against a fresh supervisor and sink — the
    /// shape every dispatch test needs now that the replay READS the socket
    /// between and during its writes (plan item 44f).
    async fn dispatch_for_test<S: DhanFeedSocket>(
        sock: &mut S,
        guard: &SubscribeGuard,
    ) -> SubscribeDispatch {
        let mut supervisor = sup(DhanEndpointType::MainFeed, 0, t0());
        let sink = RecordingSink::default();
        let mut throttle = DrainThrottle::default();
        dispatch_subscribe(
            sock,
            &mut supervisor,
            &sink,
            &mut throttle,
            guard,
            DhanEndpointType::MainFeed,
            0,
        )
        .await
        .0
    }
    // -- subscribe dispatch pacing (WS-GAP-02) ------------------------------

    /// The defect: batches went out back to back with no spacing, and a
    /// throttled subscribe is INVISIBLE — no error, no ack, no sequence
    /// number, just an instrument that never ticks.
    ///
    /// Pacing is between messages, so `n` batches cost `n - 1` intervals.
    #[tokio::test(start_paused = true)]
    async fn subscribe_batches_are_paced_by_the_named_interval() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            idle_when_exhausted: true,
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        // 250 main-feed instruments = 3 messages at the documented 100/message.
        let guard = SubscribeGuard::try_new(DhanEndpointType::MainFeed, (0..250).map(si).collect())
            .unwrap();
        assert_eq!(guard.batch_count(), 3, "documented 100 instruments/message");

        let out = dispatch_for_test(&mut sock, &guard).await;

        assert_eq!(out.batches_sent, 3);
        assert_eq!(out.instruments_sent, 250);
        assert!(!out.stopped_early());
        assert_eq!(out.instruments_undispatched(), 0);
        // The bite: before pacing this was ~0. Two gaps for three messages.
        assert_eq!(
            out.elapsed,
            SUBSCRIBE_BATCH_INTERVAL * 2,
            "three batches must be spaced by exactly two intervals"
        );
        assert_eq!(st.lock().unwrap().subscribes, 3);
    }

    /// A one-batch set is not paced at all: there is nothing before the first
    /// message to be polite to, and the deadline is waiting on it.
    #[tokio::test(start_paused = true)]
    async fn a_single_batch_dispatch_pays_no_pacing_cost() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            idle_when_exhausted: true,
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let guard =
            SubscribeGuard::try_new(DhanEndpointType::MainFeed, (0..40).map(si).collect()).unwrap();

        let out = dispatch_for_test(&mut sock, &guard).await;

        assert_eq!(out.batches_sent, 1);
        assert_eq!(out.elapsed, Duration::ZERO);
    }

    /// An empty set dispatches zero of zero and is a legal no-op, NOT a
    /// failure — otherwise the order-update socket, which carries no
    /// instruments, would park itself on every connect.
    #[tokio::test(start_paused = true)]
    async fn an_empty_set_is_a_no_op_not_an_early_stop() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            idle_when_exhausted: true,
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let guard = SubscribeGuard::try_new(DhanEndpointType::MainFeed, Vec::new()).unwrap();

        let out = dispatch_for_test(&mut sock, &guard).await;

        assert!(!out.stopped_early());
        assert_eq!(out.batches_total, 0);
        assert_eq!(st.lock().unwrap().subscribes, 0);
    }

    /// The silent half of the defect: a send that fails part-way leaves a tail
    /// that was never written. Before this, the loop returned a bare `bool`
    /// and the size of that tail was unrecorded — indistinguishable from
    /// instruments that were subscribed and merely quiet.
    #[tokio::test(start_paused = true)]
    async fn a_mid_loop_send_failure_counts_the_undispatched_tail() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            // batch 1 ok, batch 2 fails; batch 3 must never be attempted.
            idle_when_exhausted: true,
            subscribe_results: VecDeque::from(vec![true, false]),
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let guard = SubscribeGuard::try_new(DhanEndpointType::MainFeed, (0..250).map(si).collect())
            .unwrap();

        let out = dispatch_for_test(&mut sock, &guard).await;

        assert!(out.stopped_early(), "a short write must be reported");
        assert_eq!(out.batches_sent, 1);
        assert_eq!(out.batches_total, 3);
        assert_eq!(out.instruments_sent, 100);
        assert_eq!(
            out.instruments_undispatched(),
            150,
            "150 instruments were named on the set and never written to the socket"
        );
        assert_eq!(
            st.lock().unwrap().subscribes,
            2,
            "the dispatch must STOP at the failure, not press on into a broken socket"
        );
    }

    /// A failed dispatch must not leave the guard claiming a subscription the
    /// wire never carried — the next connect replays the WHOLE set.
    #[tokio::test(start_paused = true)]
    async fn an_early_stop_leaves_the_guard_unconfirmed_for_a_whole_replay() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            idle_when_exhausted: true,
            subscribe_results: VecDeque::from(vec![false]),
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let mut guard =
            SubscribeGuard::try_new(DhanEndpointType::MainFeed, (0..250).map(si).collect())
                .unwrap();

        let out = dispatch_for_test(&mut sock, &guard).await;
        // Mirrors the caller: `mark_confirmed` is reached only on a full send.
        if !out.stopped_early() {
            guard.mark_confirmed();
        }

        assert!(guard.needs_resubscribe());
        assert_eq!(guard.generation(), 0);
        assert_eq!(
            guard.batch_count(),
            3,
            "the retained set is replayed whole, never resumed from an offset"
        );
    }

    /// The deadline this pacing must not threaten, proven arithmetically
    /// against the named constants rather than by wall clock.
    #[test]
    fn subscribe_dispatch_fits_the_preopen_budget() {
        // Pin the mirrored deadline so a drift from the app crate's own
        // `PREOPEN_READY_DEADLINE_IST_SECS` fails HERE.
        assert_eq!(PREOPEN_READY_DEADLINE_IST_SECS, 9 * 3_600 + 12 * 60);
        assert_eq!(PREOPEN_ATTACH_WINDOW_OPEN_IST_SECS, 9 * 3_600);
        let budget_ms =
            u128::from(PREOPEN_READY_DEADLINE_IST_SECS - PREOPEN_ATTACH_WINDOW_OPEN_IST_SECS)
                * 1_000;
        assert_eq!(budget_ms, 720_000, "09:00 -> 09:12 IST");

        // Worst case per endpoint: a FULL pool, every connection at its
        // documented instrument cap, batched at its documented per-message cap.
        let mut worst_case_messages = 0_u128;
        for endpoint in [
            DhanEndpointType::MainFeed,
            DhanEndpointType::Depth20,
            DhanEndpointType::Depth200,
        ] {
            let per_conn = u128::from(endpoint.max_instruments_per_connection());
            let per_msg = u128::from(endpoint.max_instruments_per_subscribe_message()).max(1);
            let msgs_per_conn = per_conn.div_ceil(per_msg);
            worst_case_messages += msgs_per_conn * u128::from(endpoint.max_connections());
        }
        assert_eq!(
            worst_case_messages, 260,
            "5x50 main-feed + 5x1 depth-20 + 5x1 depth-200 messages"
        );

        // Pacing is BETWEEN messages, so n messages cost n-1 intervals. Costed
        // as if every connection dispatched serially — they do not, each runs
        // in its own task, so this is a ceiling on the real cost.
        let interval_ms = SUBSCRIBE_BATCH_INTERVAL.as_millis();
        let worst_case_ms = (worst_case_messages - 1) * interval_ms;
        assert_eq!(worst_case_ms, 6_475, "260 messages, 25 ms apart");

        // The pacing may not consume more than 5% of the pre-open budget: it
        // shares that window with dialing, the pricing quorum and contract
        // selection, so "merely under the deadline" is not the bar.
        assert!(
            worst_case_ms * 20 < budget_ms,
            "paced dispatch {worst_case_ms} ms must stay under 5% of the {budget_ms} ms \
             pre-open budget"
        );
    }

    /// One connection's worst case — the number that actually matters, since
    /// connections dispatch concurrently.
    #[test]
    fn one_full_main_feed_connection_dispatches_in_about_a_second() {
        let e = DhanEndpointType::MainFeed;
        let msgs = u128::from(e.max_instruments_per_connection())
            .div_ceil(u128::from(e.max_instruments_per_subscribe_message()));
        assert_eq!(msgs, 50, "5,000 instruments at 100 per message");
        let ms = (msgs - 1) * SUBSCRIBE_BATCH_INTERVAL.as_millis();
        assert_eq!(ms, 1_225);
        assert!(ms < 2_000);
    }

    #[tokio::test(start_paused = true)]
    async fn test_run_connection_dials_subscribes_and_drains_every_frame() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: VecDeque::from(vec![
                SocketEvent::Frame(Bytes::from_static(b"aaaaaaaa")),
                SocketEvent::Frame(Bytes::from_static(b"bbbbbbbb")),
                SocketEvent::Frame(Bytes::from_static(b"cccccccc")),
            ]),
            // The replay reads the socket while it writes (plan item 44f);
            // hold the frames until all three batches are out so the
            // terminator cannot end the replay part-way.
            recv_after_subscribes: VecDeque::from(vec![3, 3, 3]),
            terminator_after_subscribes: 3,
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::MainFeed, instruments(250))
            .expect("inside cap");

        let exit = run_connection(
            fake(&st),
            sup(DhanEndpointType::MainFeed, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
        )
        .await;

        assert_eq!(exit, ConnectionExit::Parked(ParkReason::FatalDisconnect));
        let seen = sink.accepted.lock().map(|g| g.len()).unwrap_or(0);
        assert_eq!(seen, 3, "every frame must reach the sink exactly once");
        let s = st.lock().expect("fake state");
        assert_eq!(s.connects, 1);
        assert_eq!(s.subscribes, 3, "250 instruments = three 100-cap messages");
    }

    // The whole ATM +/- 25 mechanism, end to end through the real drain loop.
    //
    // A live socket carrying 250 instruments is topped up with 150 more, and
    // the assertion that matters is the SUBSCRIBE COUNT: 3 messages for the
    // initial 250, then exactly 2 for the 150 added — never 5, which is what
    // re-sending the whole set would produce and what Dhan answers with 804.
    // ------------------------------------------------------------------
    // Swap over the live command channel (2026-08-26). The pure guard logic
    // is tested above; these pin the WIRE behaviour, which is where the
    // 804-shaped mistakes live.
    // ------------------------------------------------------------------

    fn one_scripted_frame() -> VecDeque<SocketEvent> {
        VecDeque::from(vec![
            SocketEvent::Frame(Bytes::from_static(b"aaaaaaaa")),
            SocketEvent::Frame(Bytes::from_static(b"bbbbbbbb")),
        ])
    }

    /// THE safety property. A depth-200 connection holds exactly one
    /// instrument; subscribing before unsubscribing asks for two, and Dhan
    /// answers an over-limit subscribe with 804, and retrying
    /// re-sends the identical over-limit set forever.
    #[tokio::test(start_paused = true)]
    async fn a_swap_unsubscribes_before_it_subscribes() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        tx.send(LiveSubscriptionCommand::Swap {
            old: si(1),
            new: si(2),
            ack: None,
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let s = st.lock().expect("fake state");
        // The initial subscribe, then the swap's unsubscribe, then its
        // subscribe. The ORDER of the last two is the assertion.
        assert_eq!(
            s.wire_calls,
            vec!["subscribe", "unsubscribe", "subscribe"],
            "a swap that subscribes before unsubscribing puts a depth-200 \
             connection over its one-instrument limit"
        );
        assert_eq!(s.connects, 1, "a swap must never re-dial");
    }

    /// The swap ack (2026-09-02, audit finding 8): a swap that reached the
    /// wire answers `Held`, and the caller may advance its belief on THAT —
    /// not on `try_send` succeeding, which only proves the command was
    /// queued.
    #[tokio::test(start_paused = true)]
    async fn a_swap_that_reaches_the_wire_acks_held() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::Swap {
            old: si(1),
            new: si(2),
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx.try_recv().expect("the swap arm must answer");
        assert_eq!(outcome, SwapOutcome::Held);
        assert!(!outcome.caller_should_unmark());
        let s = st.lock().expect("fake state");
        assert_eq!(s.wire_calls, vec!["subscribe", "unsubscribe", "subscribe"]);
    }

    /// Sink whose dial permit a test flips, recording every lifecycle report
    /// (R7, 2026-10-01).
    struct PermitSink {
        permit: std::sync::atomic::AtomicBool,
        lifecycle: Mutex<Vec<(tickvault_common::ws_event_types::WsEventKind, &'static str)>>,
    }

    impl FrameSink for PermitSink {
        fn accept(&self, _frame: Bytes) -> FrameSinkOutcome {
            FrameSinkOutcome::Captured
        }

        fn on_lifecycle(
            &self,
            kind: tickvault_common::ws_event_types::WsEventKind,
            reason: &'static str,
        ) {
            if let Ok(mut g) = self.lifecycle.lock() {
                g.push((kind, reason));
            }
        }

        fn dial_permitted(&self) -> bool {
            self.permit.load(std::sync::atomic::Ordering::Acquire)
        }
    }

    /// R7 (2026-10-01): a process that does not hold the dual-instance lock
    /// waits WITHOUT dialling, reports the refusal once per episode (not once
    /// per poll), costs the supervisor no dial failure, and dials as soon as
    /// the lock is held again.
    #[tokio::test(start_paused = true)]
    async fn test_run_connection_waits_without_dialling_while_lock_not_held() {
        use tickvault_common::ws_event_types::WsEventKind;

        let st = std::sync::Arc::new(Mutex::new(FakeState::default()));
        let sink = std::sync::Arc::new(PermitSink {
            permit: std::sync::atomic::AtomicBool::new(false),
            lifecycle: Mutex::new(Vec::new()),
        });
        let guard = SubscribeGuard::try_new(DhanEndpointType::MainFeed, vec![si(1)])
            .expect("one instrument");
        let task = tokio::spawn(run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::MainFeed, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            None,
        ));

        // Six polls' worth of refusal.
        tokio::time::sleep(Duration::from_secs(30)).await;
        assert_eq!(
            st.lock().unwrap().connects,
            0,
            "no dial while the lock is not held"
        );
        let refusals = sink
            .lifecycle
            .lock()
            .unwrap()
            .iter()
            .filter(|(k, r)| *k == WsEventKind::DialFailed && *r == "instance_lock_not_held")
            .count();
        assert_eq!(refusals, 1, "one report per refusal episode, not per poll");
        assert!(
            !task.is_finished(),
            "a refused dial must not park the connection"
        );

        sink.permit
            .store(true, std::sync::atomic::Ordering::Release);
        // The default script is exhausted, so the connection dials, subscribes,
        // reads the fatal terminator and parks — which ends the task.
        let exit = tokio::time::timeout(Duration::from_secs(3600), task)
            .await
            .expect("the connection must dial once the lock is held")
            .expect("connection task must not panic");
        assert!(matches!(exit, ConnectionExit::Parked(_)));
        assert!(
            st.lock().unwrap().connects >= 1,
            "the lock held again must re-enable the dial"
        );
        let lifecycle = sink.lifecycle.lock().unwrap();
        assert_eq!(
            lifecycle
                .iter()
                .filter(|(_, r)| *r == "instance_lock_not_held")
                .count(),
            1,
            "the episode reported exactly once"
        );
    }

    /// The subscribe half fails on the wire after the unsubscribe landed: the
    /// socket may be EMPTY, a redial is scheduled (asserted by the sibling
    /// test above), and the caller is told `NotHeld` — but must NOT revert
    /// its belief, because the guard already names the new instrument and
    /// the replay delivers it.
    #[tokio::test(start_paused = true)]
    async fn a_swap_whose_subscribe_fails_on_the_wire_acks_not_held_emptied() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            // The initial dispatch succeeds; the swap's subscribe does not.
            subscribe_results: VecDeque::from(vec![true, false]),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::Swap {
            old: si(1),
            new: si(2),
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx
            .try_recv()
            .expect("the swap arm must answer BEFORE it returns for the redial");
        assert_eq!(
            outcome,
            SwapOutcome::NotHeld {
                reason: SwapOutcome::REASON_EMPTIED
            }
        );
        assert!(
            !outcome.caller_should_unmark(),
            "the guard names the new instrument and the redial replays it — reverting the \
             caller's belief would plan a refused swap every minute"
        );
    }

    /// The unsubscribe is REFUSED by the wire: the socket keeps delivering
    /// `old`, the guard is reverted to `old`, and the caller must therefore
    /// unmark — or it keeps believing `new` while the guard believes `old`, and
    /// every later minute plans a swap `try_swap` refuses as `NotSubscribed`.
    ///
    /// This is the ack that was WRONG until 2026-09-09: it returned
    /// `REASON_WIRE_FAILED`, whose `caller_should_unmark()` was `false`, under
    /// a doc claiming the guard still named `new`. It had not since the revert
    /// was added.
    #[tokio::test(start_paused = true)]
    async fn a_swap_whose_unsubscribe_is_refused_reverts_the_guard_and_asks_the_caller_to_unmark() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            // The initial dispatch succeeds; the swap's UNSUBSCRIBE is refused,
            // so the subscribe is never sent.
            unsubscribe_results: VecDeque::from(vec![false]),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::Swap {
            old: si(1),
            new: si(2),
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx.try_recv().expect("the swap arm must answer");
        assert_eq!(
            outcome,
            SwapOutcome::NotHeld {
                reason: SwapOutcome::REASON_WIRE_FAILED_REVERTED
            },
            "a refused unsubscribe that reverted the guard must say so, so the ack \
             can be derived from the revert rather than guessed from the reason"
        );
        assert!(
            outcome.caller_should_unmark(),
            "the guard was put back to `old` and the socket still delivers `old`; a \
             caller left believing `new` plans a swap the guard refuses every minute \
             for the rest of the session"
        );
    }

    /// The two wire failures must stay DISTINGUISHABLE. A timed-out unsubscribe
    /// may still have landed, so the guard is deliberately NOT reverted there
    /// and the caller must keep believing `new` — the mirror of the test above,
    /// and the reason the fix is not a boolean flip on `REASON_WIRE_FAILED`.
    #[test]
    fn only_the_reverted_wire_failure_asks_the_caller_to_unmark() {
        for (reason, expected) in [
            (SwapOutcome::REASON_REFUSED, true),
            (SwapOutcome::REASON_WIRE_FAILED_REVERTED, true),
            (SwapOutcome::REASON_WIRE_FAILED, false),
            (SwapOutcome::REASON_EMPTIED, false),
        ] {
            assert_eq!(
                SwapOutcome::NotHeld { reason }.caller_should_unmark(),
                expected,
                "`{reason}` must {} the caller to unmark: unmark exactly when the \
                 GUARD ends up naming `old`",
                if expected { "ask" } else { "not ask" }
            );
        }
        assert!(
            !SwapOutcome::Held.caller_should_unmark(),
            "a held swap moved the guard to `new` and the caller already believes it"
        );
    }

    /// A refused swap leaves the guard untouched, so the caller MUST revert.
    #[tokio::test(start_paused = true)]
    async fn a_refused_swap_acks_not_held_refused_and_asks_the_caller_to_unmark() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::Swap {
            old: si(99),
            new: si(2),
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx.try_recv().expect("the swap arm must answer");
        assert_eq!(
            outcome,
            SwapOutcome::NotHeld {
                reason: SwapOutcome::REASON_REFUSED
            }
        );
        assert!(outcome.caller_should_unmark());
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.wire_calls,
            vec!["subscribe"],
            "a refused swap touches no wire"
        );
    }

    /// The ordinary minute. An edge-triggered tracker upstream means this
    /// rarely reaches the socket at all, but when it does it must cost
    /// nothing — a re-subscribe per socket per minute is ~1,500 needless wire
