    // -- structural proofs --------------------------------------------------

    #[test]
    fn test_pool_supervisor_source_never_reads_the_wall_clock() {
        // An NTP step must be unable to expire all sixteen sockets at once.
        let src = include_str!("pool_supervisor.rs");
        let test_marker = concat!("#[cfg(", "test)]");
        let production_half = src.split(test_marker).next().unwrap_or(src);
        assert!(production_half.contains("Instant"), "sanity");
        for needle in [
            concat!("System", "Time"),
            concat!("Utc", "::now"),
            concat!("chr", "ono"),
            concat!("UNIX_", "EPOCH"),
            concat!("Local", "::now"),
        ] {
            assert!(
                !production_half.contains(needle),
                "pool supervisor production code must never touch the wall clock, \
                 found `{needle}`"
            );
        }
    }

    #[test]
    fn test_drain_loop_body_does_nothing_but_capture_and_watchdog() {
        // THE ONE RULE, as a build-failing structural assertion. If a future
        // change adds parsing, a database write, or a lock to the per-frame
        // path, this fails before it can cost us the pong.
        let src = include_str!("pool_supervisor.rs");
        let test_marker = concat!("#[cfg(", "test)]");
        let production_half = src.split(test_marker).next().unwrap_or(src);
        let drain_body = production_half
            .split("async fn drain<S, K>")
            .nth(1)
            .unwrap_or("");
        assert!(
            drain_body.contains("sink.accept(frame)"),
            "sanity: the drain body must still be the real one"
        );
        for banned in [
            concat!("dispatch_", "frame"),
            concat!("parse_", "depth"),
            concat!("consume_", "tick"),
            concat!(".lock", "()"),
            concat!("questdb", ""),
            concat!("write_", "row"),
        ] {
            assert!(
                !drain_body.contains(banned),
                "the drain loop must do nothing but append+push per frame; found `{banned}`. \
                 Dhan's automatic pong is only emitted while the read loop is polling, so \
                 work here does not merely lag — it gets the socket disconnected"
            );
        }
    }

    #[test]
    fn test_frame_sink_trait_is_not_async_so_a_future_impl_cannot_await() {
        // The signature IS the enforcement: an `async fn accept` would let a
        // future implementation await inside the read loop.
        let src = include_str!("pool_supervisor.rs");
        let test_marker = concat!("#[cfg(", "test)]");
        let production_half = src.split(test_marker).next().unwrap_or(src);
        let trait_body = production_half
            .split("pub trait FrameSink")
            .nth(1)
            .unwrap_or("")
            .split("}\n")
            .next()
            .unwrap_or("");
        assert!(trait_body.contains("fn accept"), "sanity");
        assert!(
            !trait_body.contains("async") && !trait_body.contains("Future"),
            "FrameSink::accept must stay synchronous"
        );
    }

    /// The WAL receipt must be WRITTEN, not merely representable.
    ///
    /// # The defect this pins
    ///
    /// TVW3 added an 8-byte `received_at_nanos` to the WAL record on
    /// 2026-08-28, and `append_with_seq_at` was written to persist it. It then
    /// had ZERO production callers: both real append sites went through
    /// `append_with_seq`, which passes `WAL_RECEIPT_UNKNOWN_NANOS`. So every
    /// record on the box carried the sentinel while the format claimed to carry
    /// a receipt, and boot replay re-stamped `now()` — the moment of REPLAY,
    /// not of arrival. Since `received_at` is the candle BUCKETING clock, that
    /// silently re-buckets every recovered frame into the minute the process
    /// happened to restart in.
    ///
    /// A format that advertises a field nothing fills is worse than one that
    /// does not advertise it, because the reader has no way to tell.
    #[test]
    fn the_capture_path_persists_the_frame_receipt() {
        let source = include_str!("pool_supervisor.rs");
        let production_half = source
            .split_once("#[cfg(test)]")
            .map_or(source, |(prod, _)| prod);
        assert!(
            production_half.contains("append_with_seq_at("),
            "FrameSink::accept must call append_with_seq_at, not append_with_seq. \
             append_with_seq records the UNKNOWN sentinel, so the TVW3 receipt field \
             would be written as 0 on every frame and replay would re-stamp now() — the \
             moment of REPLAY rather than of arrival, on the clock that buckets candles."
        );
        assert!(
            production_half.contains("receipt_nanos_from(received_at)"),
            "the receipt must be DERIVED from the `received_at` instant already stamped \
             at the top of accept, never read from a clock here: this file bans \
             wall-clock reads so an NTP step cannot expire all sixteen sockets at once, \
             and that ban is right."
        );
        assert!(
            !production_half.contains("append_with_seq(self.ws_type"),
            "no production append may go through append_with_seq — it hardcodes the \
             unknown-receipt sentinel"
        );
    }

    /// Audit PR31: the frame the drain folds and the WAL record replay reads
    /// must carry ONE receipt value, derived once. The depth and tick keys
    /// include the row stamp, so two derivations of the same instant made a
    /// replayed row miss its live twin and land as a second row.
    #[test]
    fn the_frame_and_its_wal_record_carry_one_receipt_value() {
        let source = include_str!("pool_supervisor.rs");
        let production_half = source
            .split_once("#[cfg(test)]")
            .map_or(source, |(prod, _)| prod);
        let accept = production_half
            .split_once("fn accept(&self, frame: Bytes) -> FrameSinkOutcome {")
            .map(|(_, rest)| rest)
            .expect("FrameSink::accept must exist");
        assert_eq!(
            accept.matches("receipt_nanos_from(").count(),
            1,
            "accept must derive the receipt exactly once"
        );
        assert!(
            accept.contains(
                "let received_at_nanos = tickvault_storage::ws_frame_spill::receipt_nanos_from(received_at);"
            ),
            "the one derivation must be bound to `received_at_nanos`"
        );
        let wal = accept
            .split_once("append_with_seq_at(")
            .map(|(_, rest)| rest)
            .expect("the WAL append");
        assert!(
            wal.split_once("== AppendOutcome::Dropped")
                .is_some_and(|(args, _)| args.contains("received_at_nanos,")),
            "the WAL record must be written with that same value"
        );
        let ring = accept
            .split_once(".try_send(CapturedFrame {")
            .map(|(_, rest)| rest)
            .expect("the ring hand-off");
        assert!(
            ring.split_once('}')
                .is_some_and(|(fields, _)| fields.contains("received_at_nanos,")),
            "the published frame must carry that same value"
        );
    }

    /// The anchor the receipt is derived from must be RE-TAKEN, not boot-only.
    ///
    /// `Instant` is CLOCK_MONOTONIC and `SystemTime` is CLOCK_REALTIME; NTP
    /// SLEWS the latter at up to 500 ppm, so a single boot anchor drifts ~1.8 s
    /// per hour — ~16 s over a session. On the candle bucketing clock that
    /// files bars in the wrong second by a margin that GROWS all day, which is
    /// the error shape hardest to notice and hardest to reconstruct afterwards.
    #[test]
    fn the_receipt_anchor_is_refreshed_off_the_hot_path() {
        let lane = include_str!("../../../app/src/dhan_feed_stack.rs");
        let production_half = lane
            .split_once("#[cfg(test)]")
            .map_or(lane, |(prod, _)| prod);
        assert!(
            production_half.contains("refresh_receipt_anchor()"),
            "some off-hot-path timer must re-take the receipt anchor; a boot-only anchor \
             drifts against the wall clock under NTP slew for the whole session"
        );
        let refresh = production_half
            .rfind("refresh_receipt_anchor()")
            .expect("checked above");
        let silence_arm = production_half
            .rfind("silence_timer.tick()")
            .expect("the lane must still have its 30s silence timer");
        assert!(
            silence_arm < refresh,
            "the refresh must sit on the 30s silence arm, never the 500 ms flush arm: it \
             is a wall-clock syscall plus an allocation, and 30 s already bounds the drift \
             to ~15 ms at the worst permitted slew — three orders of magnitude inside a \
             one-second bucket."
        );
    }

    /// EVERY degraded frame outcome must throttle its log line.
    ///
    /// This is not a style rule. The three arms live on the task that OWNS
    /// THE SOCKET, and two of them fire exactly when the write-ahead writer
    /// is stalled behind a saturated disk — thousands of times a second. An
    /// unthrottled line there spends the read task on `tracing` field capture
    /// and JSON formatting instead of on `recv()`, which is what Dhan's
    /// backpressure layer classifies as a slow consumer; a slow consumer is
    /// skipped forward to "the latest available state", and with no sequence
    /// number in the protocol those ticks are gone with nothing to count
    /// them. The log storm also overruns `non_blocking`'s bounded queue, so
    /// it erases its own evidence.
    ///
    /// `RingFull` carried this throttle from 2026-08-11 and its comment
    /// states the rule — "A slow consumer must not be able to drown the log
    /// it is being reported in." `WalDropped` and `CapturedLiveOnly` sat in
    /// the SAME `match` without it until 2026-09-05. That is why this guard
    /// checks all three by name rather than trusting the rule to be read.
    #[test]
    fn every_degraded_frame_outcome_throttles_its_log() {
        let src = include_str!("pool_supervisor.rs");
        let marker = concat!("#[cfg(", "test)]");
        let production = src.split(marker).next().unwrap_or(src);

        // Anchor on the match arms themselves. Each arm's span runs to the
        // start of the next one, so a throttle belonging to a NEIGHBOUR can
        // never satisfy the arm under test — the failure mode that would make
        // this guard pass vacuously.
        let arms = [
            (
                "FrameSinkOutcome::WalDropped",
                "wal_dropped_seen",
                "FrameSinkOutcome::CapturedLiveOnly",
            ),
            (
                "FrameSinkOutcome::CapturedLiveOnly",
                "captured_live_only_seen",
                "FrameSinkOutcome::RingFull",
            ),
            (
                "FrameSinkOutcome::RingFull",
                "ring_full_seen",
                "\n        }",
            ),
        ];

        for (outcome, counter, next) in arms {
            let arm_start = production
                .rfind(&format!("if outcome == {outcome} {{"))
                .unwrap_or_else(|| panic!("the {outcome} arm must exist on the read task"));
            let rest = &production[arm_start..];
            let arm = rest.split(next).next().unwrap_or(rest);

            assert!(
                arm.contains(&format!("{counter}.is_power_of_two()")),
                "the {outcome} arm must gate its log on {counter}.is_power_of_two(). \
                 It runs on the socket-owning task; an unthrottled line there converts a \
                 stalled disk into a stalled reader, and a stalled reader is what gets us \
                 skipped forward by the vendor with no sequence number to detect it."
            );
            assert!(
                arm.contains(&format!("{counter} = {counter}.saturating_add(1)")),
                "the {outcome} arm must advance {counter} with saturating_add — a wrapping \
                 counter would silently restart the power-of-two ladder and re-open the storm"
            );
        }

        // The counters must be per-CONNECTION values, so a reconnect restarts
        // each ladder. A `static` would make the first backed-up socket of the
        // session silence every later one. Since 2026-09-22 (plan item 44f)
        // they live in `DrainThrottle`, built fresh for every connection
        // attempt, so the replay's reads and the drain's reads share one
        // ladder; the per-connection restart is unchanged.
        let throttle_struct = production
            .split("struct DrainThrottle {")
            .nth(1)
            .and_then(|rest| rest.split('}').next())
            .expect("DrainThrottle must exist");
        for counter in [
            "ring_full_seen",
            "wal_dropped_seen",
            "captured_live_only_seen",
        ] {
            assert!(
                throttle_struct.contains(&format!("{counter}: u64,")),
                "{counter} must be a DrainThrottle field: a process-wide counter would let \
                 one early storm mute every socket for the rest of the session"
            );
            assert!(
                !production.contains(&format!("static {counter}"))
                    && !production.contains(&format!("static {}", counter.to_uppercase())),
                "{counter} must never become a static"
            );
        }
        assert_eq!(
            production
                .matches("let mut throttle = DrainThrottle::default();")
                .count(),
            1,
            "the throttle must be built fresh exactly once per connection attempt"
        );
        let per_attempt = production
            .split("let mut throttle = DrainThrottle::default();")
            .nth(1)
            .expect("checked above");
        assert!(
            matches!(
                (per_attempt.find("dispatch_subscribe("), per_attempt.find("fn drain<")),
                (Some(call), Some(def)) if call < def
            ),
            "the fresh throttle must be the one the replay and drain of THIS connection use"
        );
    }

    /// The swap's outer budget wins. Until 2026-09-22 that made one failure
    /// reason VACUOUS; since the writer task (plan item 44f) keeps a write
    /// past the swap's budget, the reason is reachable again — see the
    /// correction in `PoolSupervisor::new`. The ordering this test pins is
    /// unchanged and still load-bearing.
    ///
    /// `send_unsubscribe` has exactly ONE production call site and it is
    /// wrapped in `tokio::time::timeout(SWAP_WIRE_BUDGET, ..)`. Inside,
    /// `send_unsubscribe_in_mode` wraps its socket write in
    /// `SUBSCRIBE_SEND_TIMEOUT`. With 1 s outside and 10 s inside, the outer
    /// always elapses first and the inner future is DROPPED before its timeout
    /// arm can run — so
    /// `tv_dhan_ws_subscribe_failed_total{reason="unsubscribe_timeout"}` can
    /// never increment from the swap path. **(That was the pre-split code. Since
    /// 44f the writer task owns the write and keeps it past the swap budget,
    /// so the reason IS reachable — by the swap's stuck write, by probe Arm A,
    /// and by an unsubscribe-only swap. The paragraph is kept as the record of
    /// why a 2026-09-11 zero on it proved nothing.)**
    ///
    /// That matters because on 2026-09-11 a two-session read used those four
    /// reasons to exclude "our unsubscribe never reached the wire" as the cause
    /// of the depth ghosts. Three of the four are real measurements. The fourth
    /// is a tautology, and a tautology quoted as a zero is the `capped`-counter
    /// class this repository has already recorded twice.
    ///
    /// The ordering itself is CORRECT and is not the defect: a socket that
    /// cannot write a few hundred bytes in a second is sick, and holding the
    /// drain for nine more seconds to prove it is worse. The defect was that
    /// nothing said so, and that the arm which DOES fire had no seeded counter.
    #[test]
    fn the_swap_budget_wins_so_the_inner_unsubscribe_timeout_is_vacuous() {
        assert!(
            SWAP_WIRE_BUDGET < crate::websocket::connection::SUBSCRIBE_SEND_TIMEOUT,
            "SWAP_WIRE_BUDGET ({:?}) must stay BELOW SUBSCRIBE_SEND_TIMEOUT ({:?}) — it is what \
             keeps a sick socket from holding the drain for ten seconds. If this ever inverts, \
             the `unsubscribe_timeout` reason becomes reachable and the comment in \
             `PoolSupervisor::new` calling it vacuous must be corrected in the same change.",
            SWAP_WIRE_BUDGET,
            crate::websocket::connection::SUBSCRIBE_SEND_TIMEOUT,
        );
    }

    /// Every swap wire-outcome counter is seeded, and seeded by NAME from the
    /// same const the emit site uses — so a rename cannot silently orphan one.
    ///
    /// Found 2026-09-11: all six had never reached CloudWatch, and none was
    /// seeded, so their absence was not a zero (the `tv_depth_rows_spilled_total`
    /// lesson). A drop counter without its discriminator is the shape
    /// `loss_series_seeding_guard` already forbids one file over.
    #[test]
    fn every_swap_wire_outcome_counter_is_seeded_from_its_own_const() {
        let src = include_str!("pool_supervisor.rs");
        for metric in [
            SWAP_TOTAL_METRIC,
            SWAP_REFUSED_METRIC,
            SWAP_FAILED_METRIC,
            SWAP_TIMEOUT_METRIC,
            SWAP_EMPTIED_SOCKET_METRIC,
            SWAP_GUARD_REVERTED_METRIC,
        ] {
            assert!(
                !metric.is_empty() && metric.starts_with("tv_dhan_ws_swap"),
                "unexpected swap metric name: {metric}"
            );
            assert!(
                !src.contains(&format!("metrics::counter!(\"{metric}\")")),
                "{metric} is emitted as a STRING LITERAL somewhere — point the emit site at the \
                 const so the seeding list and the emit site cannot drift apart"
            );
        }
        assert!(
            src.contains(concat!("SWAP_WIRE_", "SEED_ANCHOR —")),
            "the swap wire-outcome seeding loop is gone — an unseeded counter's first increment \
             is the sample the CloudWatch agent discards, which is the one that matters"
        );
    }

    // ------------------------------------------------------------------
    // The operator-armed unsubscribe probe (scope lock, 2026-09-12).
    //
    // Two arms, and the tests below exist because a probe whose own
    // mechanism is untested cannot produce an admissible verdict — the
    // whole point of the exercise is a finding a vendor ticket can be
    // built on.
    //
    // ARM A — `ProbeUnsubscribe`: drop the instrument, put nothing back,
    // and see whether frames keep arriving.
    // ARM B — `ProbeClose`: close the socket and let the replay come back
    // WITHOUT the instrument, which tests a different mechanism entirely.
    // ------------------------------------------------------------------

    /// FAIL-CLOSED, and this is what makes Arm A depth-200-only without a
    /// flag: a socket holding more than one instrument can never satisfy
    /// the condition, so a depth-20 socket (up to 50) and a main-feed
    /// socket (thousands) are both refused by construction.
    #[tokio::test(start_paused = true)]
    async fn a_probe_unsubscribe_is_refused_unless_the_socket_holds_exactly_one() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        // Two instruments: a depth-20-shaped socket.
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth20, vec![si(1), si(2)])
            .expect("inside cap");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            drop_this: si(1),
            send_wire: true,
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth20, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx.try_recv().expect("the probe arm must answer");
        assert_eq!(
            outcome,
            ProbeUnsubscribeOutcome::Refused {
                reason: ProbeUnsubscribeOutcome::REASON_NOT_EXACTLY_ONE,
            }
        );
        assert!(!outcome.needs_restore(), "nothing was dropped");
        assert!(
            !outcome.verdict_admissible(),
            "a refused probe sent no frame — silence after it means nothing"
        );
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.unsubscribes, 0,
            "a refused probe must not reach the wire at all"
        );
    }

    /// The steering swaps depth-200 sockets every minute, so between the
    /// operator arming the probe and this command being drained the socket
    /// can legitimately be carrying a different contract. Dropping it
    /// anyway would measure a contract the baseline was never taken on.
    #[tokio::test(start_paused = true)]
    async fn a_probe_unsubscribe_is_refused_when_the_socket_moved_to_another_contract() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(7)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            // The probe named 1; the socket moved to 7.
            drop_this: si(1),
            send_wire: true,
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        assert_eq!(
            ack_rx.try_recv().expect("the probe arm must answer"),
            ProbeUnsubscribeOutcome::Refused {
                reason: ProbeUnsubscribeOutcome::REASON_DIFFERENT_INSTRUMENT,
            }
        );
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.unsubscribes, 0,
            "the wrong contract must never be dropped"
        );
    }

    /// The happy path, and the assertion that matters is the WIRE SHAPE:
    /// exactly one unsubscribe and NO subscribe after it. A swap would have
    /// put something back; Arm A must not, because a replacement instrument
    /// keeps frames flowing and makes the measurement unreadable.
    #[tokio::test(start_paused = true)]
    async fn a_probe_unsubscribe_drops_the_instrument_and_puts_nothing_back() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            drop_this: si(1),
            send_wire: true,
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx.try_recv().expect("the probe arm must answer");
        assert_eq!(outcome, ProbeUnsubscribeOutcome::Dropped);
        assert!(
            outcome.needs_restore(),
            "the socket is now empty — a probe that forgets to restore strands it"
        );
        assert!(outcome.verdict_admissible());
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.wire_calls,
            vec!["subscribe", "unsubscribe"],
            "Arm A must NOT subscribe anything after the drop — a replacement \
             instrument keeps frames flowing and makes the measurement unreadable"
        );
        assert_eq!(s.connects, 1, "Arm A must never re-dial — that is Arm B");
    }

    /// A script that ends in a RECONNECTABLE close, so the loop actually
    /// re-dials once and replays the guard before the dry script's fatal
    /// terminator parks it.
    ///
    /// This matters more than it looks: the default terminator is
    /// `AuthenticationFailed`, which is FATAL and parks WITHOUT replaying.
    /// A "the replay carries nothing" test written against the default
    /// script passes because no replay ever happens — vacuously green
    /// against correct AND incorrect code. Hence the explicit transient
    /// close, and the `connects == 2` assertion in every test that uses it.
    fn one_frame_then_a_reconnectable_close() -> VecDeque<SocketEvent> {
        VecDeque::from(vec![
            SocketEvent::Frame(Bytes::from_static(b"aaaaaaaa")),
            SocketEvent::Closed {
                code: Some(DisconnectCode::InternalServerError),
            },
        ])
    }

    /// THE GUARD SIDE of the drop, asserted through behaviour rather than
    /// by peeking at private state: the guard IS the reconnect replay, so a
    /// socket that redials after a successful probe unsubscribe must come
    /// back subscribing NOTHING.
    ///
    /// If the guard were left naming the instrument, the replay would
    /// re-subscribe it, frames would resume, and the probe would report
    /// "the vendor ignored our unsubscribe" — a negative finding
    /// manufactured by our own code, on the exact question a vendor ticket
    /// would be built on.
    #[tokio::test(start_paused = true)]
    async fn after_a_probe_unsubscribe_a_redial_replays_nothing() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_frame_then_a_reconnectable_close(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            drop_this: si(1),
            send_wire: true,
            ack: None,
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let s = st.lock().expect("fake state");
        assert_eq!(
            s.connects, 2,
            "ANTI-VACUITY: without a real re-dial the subscribe assertion below is \
             green whatever the guard holds"
        );
        assert_eq!(
            s.subscribes, 1,
            "exactly ONE subscribe — the initial dispatch. The re-dial's replay must \
             carry nothing: replaying the dropped instrument would make the watch \
             window read OUR behaviour as the vendor's"
        );
    }

    /// THE MIRROR, and the bite-proof for the wire-first ordering: when the
    /// unsubscribe does NOT reach the wire the guard must be untouched, so
    /// the very same re-dial replays the instrument.
    ///
    /// Emptying the guard before the wire call would make this replay carry
    /// nothing, stranding a socket whose subscription was never actually
    /// cancelled — and the restore would then re-subscribe what Dhan still
    /// holds, which is an 804 and the slot's one re-dial spent.
    #[tokio::test(start_paused = true)]
    async fn after_a_failed_probe_unsubscribe_the_redial_still_replays_the_instrument() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_frame_then_a_reconnectable_close(),
            unsubscribe_results: VecDeque::from(vec![false]),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            drop_this: si(1),
            send_wire: true,
            ack: None,
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let s = st.lock().expect("fake state");
        assert_eq!(
            s.connects, 2,
            "ANTI-VACUITY: the re-dial must actually happen"
        );
        assert_eq!(
            s.subscribes, 2,
            "the initial dispatch AND the replay. A failed unsubscribe must leave the \
             guard naming the instrument the socket still carries"
        );
    }

    /// A wire failure must be a CLEAN NO-OP: nothing dropped, nothing to
    /// restore, and — the part that would otherwise bite — no verdict.
    ///
    /// The guard is untouched, so the socket still carries the instrument.
    /// Had the handler emptied the guard first, the restore would have
    /// `try_extend`ed an instrument the socket already holds, and Dhan
    /// answers a duplicate subscribe with 804 — spending the slot's one
    /// re-dial and potentially parking it for the session. The probe would
    /// have broken the socket it was measuring.
    #[tokio::test(start_paused = true)]
    async fn a_probe_unsubscribe_that_fails_on_the_wire_changes_nothing() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            unsubscribe_results: VecDeque::from(vec![false]),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            drop_this: si(1),
            send_wire: true,
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        let outcome = ack_rx.try_recv().expect("the probe arm must answer");
        assert_eq!(
            outcome,
            ProbeUnsubscribeOutcome::WireFailed { timed_out: false },
            "the socket ANSWERED with an error — that is not the same fact as a timeout"
        );
        assert!(
            !outcome.needs_restore(),
            "nothing was dropped, so a restore would re-subscribe what the socket holds — 804"
        );
        assert!(
            !outcome.verdict_admissible(),
            "no frame landed, so silence afterwards would say nothing about the vendor"
        );
    }

    /// The outcome type's two questions are answered ONLY by `Dropped`.
    /// Spelled as a test because a future fourth variant defaulting to
    /// "no restore" would strand a depth-200 socket carrying nothing for
    /// the rest of the session.
    #[test]
    fn only_a_dropped_probe_needs_a_restore_or_yields_a_verdict() {
        for outcome in [
            ProbeUnsubscribeOutcome::Refused {
                reason: ProbeUnsubscribeOutcome::REASON_NOT_EXACTLY_ONE,
            },
            ProbeUnsubscribeOutcome::Refused {
                reason: ProbeUnsubscribeOutcome::REASON_DIFFERENT_INSTRUMENT,
            },
            ProbeUnsubscribeOutcome::WireFailed { timed_out: false },
            ProbeUnsubscribeOutcome::WireFailed { timed_out: true },
        ] {
            assert!(
                !outcome.needs_restore(),
                "{outcome:?} left the socket holding what it held"
            );
            assert!(
                !outcome.verdict_admissible(),
                "{outcome:?} put no frame on the wire, so nothing it is followed by is evidence"
            );
        }
        assert!(ProbeUnsubscribeOutcome::Dropped.needs_restore());
        assert!(ProbeUnsubscribeOutcome::Dropped.verdict_admissible());
    }

    // --- In place, never a redial (scope lock, 2026-10-01) --------------

    /// The depth-200 change of contract is an in-place unsubscribe then
    /// subscribe on the SAME socket. Until 2026-10-01 it closed the socket and
    /// redialled; the operator ruled that out ("isntead of disconenct
    /// reocnenct follow the unsubscribe and siubscribe apporach").
    #[tokio::test(start_paused = true)]
    async fn a_depth_200_swap_never_closes_the_socket() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_scripted_frame(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::Swap {
            old: si(1),
            new: si(9),
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        assert_eq!(ack_rx.try_recv().ok(), Some(SwapOutcome::Held));
        let s = st.lock().expect("fake state");
        assert_eq!(s.connects, 1, "the change of contract must never redial");
        assert_eq!(
            s.wire_calls,
            vec!["subscribe", "unsubscribe", "subscribe"],
            "unsubscribe the old contract, then subscribe the new one, on the live socket"
        );
        assert_eq!(s.subscribed_ids, vec![1, 9]);
        assert_eq!(
            sink.accepted.lock().map(|g| g.len()).unwrap_or(0),
            2,
            "every frame around the change reaches the sink"
        );
    }

    /// The ghost answer: the unsubscribe goes out again on the same socket,
    /// and nothing closes or dials it.
    #[tokio::test(start_paused = true)]
    async fn a_ghost_unsubscribe_resends_code_25_and_never_redials() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            idle_when_exhausted: true,
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let mut supervisor = sup(DhanEndpointType::Depth200, 0, t0());
        let sink = RecordingSink::default();
        let mut throttle = DrainThrottle::default();
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(2)])
            .expect("one instrument");

        let (outcome, decided) = resend_ghost_unsubscribe(
            &mut sock,
            &mut supervisor,
            &sink,
            &mut throttle,
            &guard,
            si(1),
        )
        .await;

        assert_eq!(outcome, "sent");
        assert_eq!(decided, None, "nothing decided the socket's fate");
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.wire_calls,
            vec!["unsubscribe"],
            "exactly one write: the resend"
        );
        assert_eq!(s.connects, 0, "a ghost must never dial");
        assert_eq!(s.closes, 0, "a ghost must never close the socket");
    }

    /// A ghost the socket has since been told to carry again is wanted:
    /// unsubscribing it would drop a live contract, so nothing is sent.
    #[tokio::test(start_paused = true)]
    async fn a_ghost_unsubscribe_for_a_held_instrument_sends_nothing() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            idle_when_exhausted: true,
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let mut supervisor = sup(DhanEndpointType::Depth20, 0, t0());
        let sink = RecordingSink::default();
        let mut throttle = DrainThrottle::default();
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth20, vec![si(1), si(2)])
            .expect("two instruments");

        let (outcome, decided) = resend_ghost_unsubscribe(
            &mut sock,
            &mut supervisor,
            &sink,
            &mut throttle,
            &guard,
            si(2),
        )
        .await;

        assert_eq!(outcome, "held_again");
        assert_eq!(decided, None);
        assert!(
            st.lock().expect("fake state").wire_calls.is_empty(),
            "a held contract must never be unsubscribed"
        );
    }

    /// A burst arriving while the resend is on the wire is read, not left in
    /// the kernel buffer: every frame reaches the sink before the write is
    /// answered, which is what keeps a slow write from costing ticks.
    #[tokio::test(start_paused = true)]
    async fn a_ghost_unsubscribe_reads_a_burst_that_arrives_during_the_write() {
        let burst: VecDeque<SocketEvent> = (0..32)
            .map(|_| SocketEvent::Frame(Bytes::from_static(b"burst...")))
            .collect();
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: burst,
            idle_when_exhausted: true,
            unsubscribe_delay: Some(Duration::from_millis(300)),
            ..FakeState::default()
        }));
        let mut sock = fake(&st);
        let mut supervisor = sup(DhanEndpointType::Depth20, 0, t0());
        let sink = RecordingSink::default();
        let mut throttle = DrainThrottle::default();
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth20, vec![si(2)])
            .expect("one instrument");

        let (outcome, _) = resend_ghost_unsubscribe(
            &mut sock,
            &mut supervisor,
            &sink,
            &mut throttle,
            &guard,
            si(1),
        )
        .await;

        assert_eq!(outcome, "sent");
        assert_eq!(
            sink.accepted.lock().map(|g| g.len()).unwrap_or(0),
            32,
            "every frame of the burst must reach the sink"
        );
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.write_answers,
            vec![("unsubscribe", 32)],
            "ANTI-VACUITY: the burst was read WHILE the write was in flight"
        );
    }

    /// Audit PR21: the probe register asks for a VOLUNTARY close-and-redial,
    /// so it reads the 805 breaker before acting. (The ghost register no
    /// longer redials since 2026-10-01; the drain reads the breaker before it
    /// asks for a resend, pinned in the app crate.)
    #[test]
    fn voluntary_redials_check_the_805_breaker_before_acting() {
        let src = include_str!("pool_supervisor.rs");
        let test_marker = concat!("#[cfg(", "test)]");
        let production = src.split(test_marker).next().unwrap_or(src);
        let (register, event) = (
            "take_probe_close(supervisor",
            "ConnEvent::ProbeCloseRequested",
        );
        {
            let at = production
                .find(register)
                .unwrap_or_else(|| panic!("{register} must still be read in the drain"));
            let tail = &production[at..];
            let breaker = tail
                .find("rotation_halted()")
                .unwrap_or_else(|| panic!("{register} must check the 805 breaker"));
            let acts = tail
                .find(event)
                .unwrap_or_else(|| panic!("{event} must follow {register}"));
            assert!(
                breaker < acts,
                "{register}: the 805 breaker must be read before {event} is raised"
            );
        }
    }

    #[test]
    fn test_refuse_voluntary_redial_after_805_does_not_panic_and_names_the_path() {
        let slot = slot(DhanEndpointType::Depth20, 0);
        refuse_voluntary_redial_after_805(slot, "probe_close");
        assert_eq!(
            DIAL_REFUSED_AFTER_805_METRIC,
            "tv_depth_dial_refused_after_805_total"
        );
    }

    /// The 805 breaker, pinned by source because the flag is process-global:
    /// setting it in a test would break every other rotation test running in
    /// parallel. The PoolOverflow arm must set it. The depth-200 change of
    /// contract reads it in the steering task before it sends a swap (pinned
    /// there, in the app crate), since 2026-10-01 the change is an ordinary
    /// in-place swap rather than a redial arm of its own.
    #[test]
    fn an_805_halts_every_later_rotation() {
        let src = include_str!("pool_supervisor.rs");
        let prod = src.split("#[cfg(test)]").next().expect("production half");
        let overflow = prod
            .find("ROTATION_HALTED.store(true")
            .expect("the PoolOverflow arm must latch the breaker");
        let park = prod[overflow..]
            .find("self.park(")
            .expect("the latch must sit before the park it guards");
        assert!(
            prod[overflow + park..].starts_with("self.park(ParkReason::PoolOverflow"),
            "the breaker must be latched in the 805 arm, immediately before its park"
        );
    }

    /// The 805 breaker at the WRITE, not only at the plan (scope lock
    /// 2026-10-01: after any 805 no depth-200 change and no ghost unsubscribe
    /// is sent). A swap can wait in the channel while the socket is down and a
    /// ghost request can be armed before the 805, so both are checked again
    /// where they would reach the wire. Pinned by source for the same reason
    /// as `an_805_halts_every_later_rotation`: the flag is process-global.
    #[test]
    fn an_805_refuses_a_queued_swap_and_a_pending_ghost_at_the_connection() {
        let src = include_str!("pool_supervisor.rs");
        let prod = src.split("#[cfg(test)]").next().expect("production half");
        let swap_arm = prod
            .find("Ok(LiveSubscriptionCommand::Swap { old, new, ack }) => {")
            .expect("the swap arm");
        let try_swap = prod[swap_arm..]
            .find("guard.try_swap(old, new)")
            .expect("the swap arm calls try_swap");
        assert!(
            prod[swap_arm..swap_arm + try_swap].contains(
                "supervisor.slot().endpoint == DhanEndpointType::Depth200 && rotation_halted()"
            ),
            "a depth-200 swap must be refused after an 805 BEFORE the guard is touched"
        );
        let resend = prod
            .find("async fn resend_ghost_unsubscribe")
            .expect("the resend");
        let send = prod[resend..]
            .find("socket.send_unsubscribe(&[ghost])")
            .expect("the resend writes the unsubscribe");
        assert!(
            prod[resend..resend + send].contains("if rotation_halted() {"),
            "a ghost unsubscribe must be refused after an 805 before it is written"
        );
    }

    #[test]
    fn test_rotation_halted_reads_the_process_latch() {
        // Read-only on purpose: the latch is process-global, and setting it
        // here would refuse every rotation test running in parallel.
        assert_eq!(
            rotation_halted(),
            ROTATION_HALTED.load(std::sync::atomic::Ordering::Acquire)
        );
    }

    // --- Arm B: the probe-close register ------------------------------

    /// ONE probe close per socket per session, and the latch is never
    /// cleared — that is what makes "at most once" a property of the code
    /// rather than of a caller's discipline. An operator who arms twice
    /// gets a refusal, not a second socket teardown.
    ///
    /// Split across three tests named for the three functions (2026-09-12)
    /// so `pub-fn-test-guard` can find the coverage by name — the house
    /// convention its sibling `request_ghost_unsubscribe_*` tests already use.
    /// Each owns its OWN slot index: the register is process-global and
    /// deliberately never cleared, so a shared index would make one test's
    /// pass depend on another's execution order.
    #[test]
    fn request_probe_close_arms_a_slot_once_and_refuses_every_arm_after() {
        let idx = 29_u8;
        assert!(!probe_close_spent(idx), "fresh slot");
        assert_eq!(request_probe_close(idx), Ok(()));
        assert_eq!(
            request_probe_close(idx),
            Err(ProbeCloseRefusal::AlreadyArmed),
            "the second arm must be refused even though the first was never taken"
        );
        assert!(take_probe_close(idx), "the first arm is still pending");
        assert_eq!(
            request_probe_close(idx),
            Err(ProbeCloseRefusal::AlreadyArmed),
            "taking the request does NOT re-arm the socket"
        );
    }

    /// The take is one-shot: the connection task polls it on every idle
    /// tick, so a take that kept returning true would close the socket
    /// once a second for the rest of the session.
    #[test]
    fn take_probe_close_takes_a_pending_arm_exactly_once() {
        let idx = 28_u8;
        assert!(!take_probe_close(idx), "nothing armed yet");
        assert_eq!(request_probe_close(idx), Ok(()));
        assert!(take_probe_close(idx), "the arm is pending");
        assert!(!take_probe_close(idx), "and it is one-shot");
    }

    /// `probe_close_spent` reports the LATCH, not the pending flag — so it
    /// stays true after the take. It is what lets a caller ask "has this
    /// socket already been used for the session's one probe?" without
    /// consuming anything.
    #[test]
    fn probe_close_spent_stays_true_once_armed_even_after_the_take() {
        let idx = 27_u8;
        assert!(!probe_close_spent(idx), "fresh slot");
        assert_eq!(request_probe_close(idx), Ok(()));
        assert!(probe_close_spent(idx), "armed");
        assert!(take_probe_close(idx));
        assert!(
            probe_close_spent(idx),
            "the latch survives the take — that is what makes it a session-long record"
        );
    }

    /// Out of range refuses rather than panicking. The register is sized
    /// for the authorized socket budget; a caller with a bad index is a
    /// bug, and a bug that takes the process down mid-session is worse
    /// than one that returns an error.
    #[test]
    fn request_probe_close_refuses_an_unknown_socket_rather_than_panicking() {
        let out_of_range = u8::try_from(GHOST_REDIAL_SLOTS).unwrap_or(u8::MAX);
        assert_eq!(
            request_probe_close(out_of_range),
            Err(ProbeCloseRefusal::OutOfRange)
        );
        assert!(!take_probe_close(out_of_range));
        assert!(!probe_close_spent(out_of_range));
    }

    /// A ghost unsubscribe and a probe close can both be pending on one
    /// socket. The ghost is taken first: it is a FAULT and the probe is a
    /// MEASUREMENT, and a measurement must never pre-empt a remediation.
    #[test]
    fn the_ghost_unsubscribe_is_taken_before_the_probe_close() {
        let src = include_str!("pool_supervisor.rs");
        let production = src
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map_or(src, |(before, _)| before);
        assert!(
            production.contains("fn take_probe_close("),
            "anti-vacuity: the production half must contain the take fn"
        );
        let ghost = production
            .find("take_ghost_unsubscribe(supervisor.slot().global_index)")
            .expect("the connection task must take ghost unsubscribes");
        let probe = production
            .find("take_probe_close(supervisor.slot().global_index)")
            .expect("the connection task must take probe closes");
        assert!(
            ghost < probe,
            "the ghost take must come FIRST: a ghost is a fault and a probe close is a \
             measurement, and a measurement must never pre-empt a remediation"
        );
    }

    /// A slot the authorized 16 sockets never use, so this test cannot be
    /// perturbed by another test driving a real connection index.
    const UNUSED_SLOT: u8 = (GHOST_REDIAL_SLOTS - 1) as u8;

    #[test]
    fn dial_generation_counts_dials_and_never_panics_out_of_range() {
        // Relative to a captured baseline, never an absolute: this register is
        // a process-global static and the suite runs in parallel.
        let before = dial_generation(UNUSED_SLOT);

        bump_dial_generation(UNUSED_SLOT);
        assert_eq!(
            dial_generation(UNUSED_SLOT),
            before + 1,
            "a completed dial must advance the slot's generation"
        );

        bump_dial_generation(UNUSED_SLOT);
        assert_eq!(dial_generation(UNUSED_SLOT), before + 2);

        // An out-of-range index reads 0 rather than panicking. The probe calls
        // this from a live steering path under `panic = "abort"`, so a bad
        // index must never take the process down.
        let out_of_range = u8::try_from(GHOST_REDIAL_SLOTS).unwrap_or(u8::MAX);
        assert_eq!(dial_generation(out_of_range), 0);
        assert_eq!(dial_generation(u8::MAX), 0);

        // And a bump on an out-of-range index is a silent no-op, not a write
        // into a neighbouring slot.
        let neighbour = dial_generation(UNUSED_SLOT);
        bump_dial_generation(out_of_range);
        bump_dial_generation(u8::MAX);
        assert_eq!(
            dial_generation(UNUSED_SLOT),
            neighbour,
            "an out-of-range bump wrote into a real slot"
        );
    }

    #[test]
    fn dial_generation_is_independent_per_slot() {
        // Arm A requires the generation UNCHANGED and Arm B requires it MOVED,
        // each on its OWN socket — so a bump on one slot must never be
        // readable as a bump on the other, or the two arms contaminate.
        // Slots DISJOINT from the ones the test above bumps: these two tests
        // share the process-global register and cargo runs them in parallel,
        // so overlapping slots would make each one flake the other.
        let a = UNUSED_SLOT - 3;
        let b = UNUSED_SLOT - 2;
        let (a0, b0) = (dial_generation(a), dial_generation(b));

        bump_dial_generation(a);
        assert_eq!(dial_generation(a), a0 + 1);
        assert_eq!(
            dial_generation(b),
            b0,
            "a dial on one slot advanced another slot's generation"
        );
    }

    /// The PRODUCTION WIRING of [`bump_dial_generation`], driven through the
    /// real state machine (2026-09-13).
    ///
    /// The two tests above call `bump_dial_generation` DIRECTLY. Nothing drove
    /// [`ConnEvent::DialSucceeded`], so deleting the single production call
    /// site left the function still referenced — by tests — and it would not
    /// even raise `dead_code`, which is what caught an earlier finding of this
    /// same class. A helper with a test and no caller is the skeleton shape
    /// `audit-findings-2026-04-17.md` Rule 14 forbids.
    ///
    /// The consequence of that regression is silent and severe: the counter
    /// never moves, so `dials_after == dials_before` FOREVER. Arm A of the
    /// unsubscribe probe then returns `Honoured` on a socket that genuinely
    /// re-dialled — the false vendor-blaming finding the generation check
    /// exists to prevent, on the exact question a vendor ticket is built on —
    /// and Arm B, which requires the counter to have MOVED, can never return a
    /// verdict at all.
    #[test]
    fn a_dial_succeeded_event_advances_the_slot_generation() {
        // A slot DISJOINT from every other test that touches this register:
        // the authorized sockets index 0..16, and the two tests above use
        // UNUSED_SLOT, UNUSED_SLOT - 3 and UNUSED_SLOT - 2. `DIAL_GENERATION`
        // is a process-global static and cargo runs the suite in parallel, so
        // an overlapping slot makes these tests flake each other.
        const PROD_WIRING_SLOT: u8 = UNUSED_SLOT - 5;
        let now = t0();
        let mut s = ConnectionSupervisor::new(
            ConnectionSlot {
                account: crate::websocket::pool_budget::DhanAccount::Primary,
                endpoint: DhanEndpointType::Depth200,
                pool_index: 0,
                global_index: PROD_WIRING_SLOT,
            },
            now,
        );
        // Relative to a captured baseline, never an absolute — same reason.
        let before = dial_generation(PROD_WIRING_SLOT);

        let _ = s.on_event(ConnEvent::BeginDial, now);
        assert_eq!(
            dial_generation(PROD_WIRING_SLOT),
            before,
            "ANTI-VACUITY: a dial that has only BEGUN must not count, or this \
             test would pass against a bump moved to the wrong arm — and a \
             dial that hangs forever would read as a completed re-dial"
        );

        assert_eq!(
            s.on_event(ConnEvent::DialSucceeded, now),
            SupervisorAction::Subscribe
        );
        assert_eq!(
            dial_generation(PROD_WIRING_SLOT),
            before + 1,
            "the `ConnEvent::DialSucceeded` arm no longer records the dial — \
             the probe's re-dial defence is dead, and every Arm A verdict \
             reads `Honoured` whether the socket re-dialled or not"
        );

        // A SECOND cycle, because the probe reads the counter either side of a
        // watch window: the register must track EVERY confirmed dial, not just
        // the first, or a re-dial inside that window is invisible.
        let later = now + Duration::from_secs(1);
        let _ = s.on_event(ConnEvent::BeginDial, later);
        let _ = s.on_event(ConnEvent::DialSucceeded, later);
        assert_eq!(
            dial_generation(PROD_WIRING_SLOT),
            before + 2,
            "a re-dial inside the watch window must be visible to the probe"
        );
    }

    /// The fail-open edge, DOCUMENTED rather than fixed (2026-09-13).
    ///
    /// [`dial_generation`] returns `0` for an out-of-range index on BOTH the
    /// before and the after read, so `redialled` is `false` however many dials
    /// occurred and Arm A's `Silent` yields `Honoured` from a comparison that
    /// proved nothing. It is unreachable at 16 authorized sockets against 32
    /// slots; it becomes reachable the moment the connection count is raised
    /// past the slot count, and it fails SILENTLY and in the reassuring
    /// direction. Recorded here, and at [`dial_generation`], so a session that
    /// raises the budget sees the consequence rather than discovering it.
    #[test]
    fn dial_generation_out_of_range_makes_the_probe_check_vacuous() {
        let out_of_range = u8::try_from(GHOST_REDIAL_SLOTS).unwrap_or(u8::MAX);

        // The probe's own comparison, spelled out: read, re-dial, read.
        let before = dial_generation(out_of_range);
        bump_dial_generation(out_of_range);
        bump_dial_generation(out_of_range);
        let after = dial_generation(out_of_range);

        assert_eq!(before, 0);
        assert_eq!(after, 0);
        assert_eq!(
            after, before,
            "DOCUMENTED, NOT DESIRED: two dials happened and the check cannot \
             see either, so Arm A would report `Honoured` on a socket that \
             re-dialled"
        );

        // The invariant that keeps the edge unreachable. If this ever fails,
        // some authorized socket has no generation slot and its probe verdict
        // is vacuous — raise GHOST_REDIAL_SLOTS in the same change that raises
        // the connection budget.
        assert!(
            usize::from(MAX_TOTAL_DHAN_CONNECTIONS) <= GHOST_REDIAL_SLOTS,
            "every authorized socket must have a real generation slot, or the \
             probe's re-dial defence is vacuous for the ones that do not"
        );
    }

    /// Arm B's `send_wire: false` branch at the SUPERVISOR, end to end
    /// (2026-09-13).
    ///
    /// All six `ProbeUnsubscribe` tests before this one passed
    /// `send_wire: true`; the probe-side test asserts only that the COMMAND
    /// carries `!send_wire`. Nothing asserted that the supervisor HONOURS it —
    /// so the `else { true }` branch that empties the guard and sends no frame
    /// had zero coverage, on the arm whose whole mechanism is the
    /// close-and-redial.
    ///
    /// Both halves matter and they fail in opposite directions:
    ///
    /// * a frame that DOES go out makes Arm B into Arm A, measuring the
    ///   vendor's unsubscribe handling instead of the re-dial replay;
    /// * a guard that is NOT emptied makes the re-dial re-subscribe the
    ///   instrument, frames resume, and Arm B measures our own replay.
    #[tokio::test(start_paused = true)]
    async fn a_probe_unsubscribe_with_send_wire_false_empties_the_guard_without_a_frame() {
        let st = std::sync::Arc::new(Mutex::new(FakeState {
            recv_events: one_frame_then_a_reconnectable_close(),
            ..FakeState::default()
        }));
        let sink = std::sync::Arc::new(RecordingSink::default());
        let guard = SubscribeGuard::try_new(DhanEndpointType::Depth200, vec![si(1)])
            .expect("one instrument");
        let (tx, rx) = tokio::sync::mpsc::channel(1);
        let (ack_tx, mut ack_rx) = tokio::sync::oneshot::channel();
        tx.send(LiveSubscriptionCommand::ProbeUnsubscribe {
            drop_this: si(1),
            send_wire: false,
            ack: Some(ack_tx),
        })
        .await
        .expect("channel open");
        drop(tx);

        let _ = run_connection_with_commands(
            fake(&st),
            sup(DhanEndpointType::Depth200, 0, t0()),
            guard,
            std::sync::Arc::clone(&sink),
            || async {},
            Some(rx),
        )
        .await;

        assert_eq!(
            ack_rx.try_recv().expect("the probe arm must answer"),
            ProbeUnsubscribeOutcome::Dropped,
            "Arm B asks for no frame, and that request cannot fail — the \
             outcome must be `Dropped`, never `WireFailed`"
        );
        let s = st.lock().expect("fake state");
        assert_eq!(
            s.unsubscribes, 0,
            "`send_wire: false` means NO unsubscribe frame reaches the wire — \
             a frame here would make Arm B indistinguishable from Arm A"
        );
        assert_eq!(
            s.wire_calls,
            vec!["subscribe"],
            "the initial dispatch and nothing else"
        );
        assert_eq!(
            s.connects, 2,
            "ANTI-VACUITY: without a real re-dial the replay assertion below \
             is green whatever the guard holds"
        );
        assert_eq!(
            s.subscribes, 1,
            "THE GUARD SIDE: emptied without a frame, so the re-dial's replay \
             carries nothing. Were the branch to leave the guard holding the \
             instrument, the replay would re-subscribe it and Arm B would be \
             measuring our own replay rather than the vendor"
        );
    }

    // ---- reconnect + swap latency (2026-09-13) ---------------------------
    //
    // The operator asked for two numbers that did not exist: how long a socket
    // takes to come back, and how long a resubscribe spends on the wire. Both
    // were BOUNDED and neither was MEASURED — `SWAP_WIRE_BUDGET` is a timeout,
    // and `RECONNECT_METRIC` counts re-dials without ever timing one.

    /// The metric names are the operator-facing surface; pin them.
    #[test]
    fn the_three_latency_metric_names_are_pinned() {
        assert_eq!(DIAL_MS_METRIC, "tv_dhan_ws_dial_ms");
        assert_eq!(
            RECONNECT_RECOVERY_MS_METRIC,
            "tv_dhan_ws_reconnect_recovery_ms"
        );
        assert_eq!(SWAP_WIRE_MS_METRIC, "tv_dhan_ws_swap_wire_ms");
        // `observability.rs` buckets on a `_ms` SUFFIX. A rename that drops it
        // silently re-buckets these into the default (seconds) ladder, where a
        // 300 ms dial lands in the first bucket forever.
        for name in [
            DIAL_MS_METRIC,
            RECONNECT_RECOVERY_MS_METRIC,
            SWAP_WIRE_MS_METRIC,
        ] {
            assert!(
                name.ends_with("_ms"),
                "{name} must keep the _ms suffix the histogram bucketing keys on"
            );
        }
    }

    /// A dial that completes and then delivers records BOTH numbers, and the
    /// second frame records nothing more.
    #[test]
    fn a_dial_records_transport_time_then_recovery_time_once() {
        let start = Instant::now();
        let mut conn = sup(DhanEndpointType::MainFeed, 0, start);

        assert!(
            conn.dial_started_at.is_none(),
            "an idle supervisor has no dial in flight"
        );

        conn.on_event(ConnEvent::BeginDial, start);
        let stamped = conn
            .dial_started_at
            .expect("BeginDial must stamp the dial start");
        assert_eq!(stamped, start);

        // DialSucceeded READS the stamp — it must not consume it, or the
        // recovery measurement below has nothing left to measure from.
        conn.on_event(ConnEvent::DialSucceeded, start + Duration::from_millis(120));
        assert_eq!(
            conn.dial_started_at,
            Some(start),
            "the transport-time record must not take the stamp the recovery record needs"
        );

        // First frame TAKES it.
        conn.on_event(ConnEvent::FrameReceived, start + Duration::from_millis(900));
        assert!(
            conn.dial_started_at.is_none(),
            "the first frame must consume the stamp so a second frame cannot record again"
        );

        // Second frame: nothing left to record.
        conn.on_event(ConnEvent::FrameReceived, start + Duration::from_millis(950));
        assert!(conn.dial_started_at.is_none());
    }

    /// A re-dial must not measure from the PREVIOUS dial. Without the
    /// overwrite in `BeginDial` a failed dial leaks its stamp forward and the
    /// next socket reports a recovery time that includes the failure.
    #[test]
    fn a_redial_measures_from_its_own_begin_not_the_failed_one() {
        let start = Instant::now();
        let mut conn = sup(DhanEndpointType::MainFeed, 0, start);

        conn.on_event(ConnEvent::BeginDial, start);
        assert_eq!(conn.dial_started_at, Some(start));

        // That dial fails — the stamp is still the old one.
        conn.on_event(ConnEvent::DialFailed, start + Duration::from_millis(200));

        let second = start + Duration::from_secs(5);
        conn.on_event(ConnEvent::BeginDial, second);
        assert_eq!(
            conn.dial_started_at,
            Some(second),
            "a fresh dial must re-stamp, or its recovery time carries the failed attempt"
        );
    }

    /// The recovery clock spans the WHOLE outage. A socket that was live,
    /// lost the connection, failed two dials and then recovered must be timed
    /// from the loss — not from its last (fast) dial, which is what a
    /// per-dial stamp reported before 2026-09-25.
    #[test]
    fn recovery_is_timed_from_the_loss_across_failed_redials() {
        let start = Instant::now();
        let mut conn = sup(DhanEndpointType::MainFeed, 0, start);

        // A healthy session first, so the next loss is a genuine re-dial.
        conn.on_event(ConnEvent::BeginDial, start);
        conn.on_event(ConnEvent::DialSucceeded, start + Duration::from_millis(100));
        conn.on_event(
            ConnEvent::SubscribeAcked,
            start + Duration::from_millis(150),
        );
        conn.on_event(ConnEvent::FrameReceived, start + Duration::from_millis(200));
        assert!(conn.outage_started_at.is_none(), "the first frame takes it");

        let lost = start + Duration::from_secs(60);
        conn.on_event(ConnEvent::Disconnected { code: None }, lost);
        assert_eq!(
            conn.outage_started_at,
            Some(lost),
            "the outage starts at the loss, so the backoff sleep is measured"
        );

        // Two failed dials: the per-dial stamp moves, the outage stamp does not.
        conn.on_event(ConnEvent::BeginDial, lost + Duration::from_secs(1));
        conn.on_event(ConnEvent::DialFailed, lost + Duration::from_secs(2));
        let last_dial = lost + Duration::from_secs(20);
        conn.on_event(ConnEvent::BeginDial, last_dial);
        assert_eq!(conn.dial_started_at, Some(last_dial));
        assert_eq!(
            conn.outage_started_at,
            Some(lost),
            "a retry must never restart the outage clock"
        );

        conn.on_event(
            ConnEvent::DialSucceeded,
            last_dial + Duration::from_millis(100),
        );
        conn.on_event(
            ConnEvent::SubscribeAcked,
            last_dial + Duration::from_millis(150),
        );
        conn.on_event(ConnEvent::FrameReceived, last_dial + Duration::from_secs(1));
        assert!(
            conn.outage_started_at.is_none() && conn.dial_started_at.is_none(),
            "recovery consumes both stamps, so the next outage starts clean"
        );
    }

    /// Placement, not existence. Each of these is a way the measurement could
    /// be present and wrong.
    #[test]
    fn the_latency_records_sit_where_they_measure_the_right_thing() {
        let src = include_str!("pool_supervisor.rs");
        let test_marker = concat!("#[cfg(", "test)]");
        let production = src
            .split_once(&format!("\n{test_marker}"))
            .map_or(src, |(head, _)| head);

        // Non-vacuity: the scan must be looking at real production text.
        assert!(
            production.contains("ConnEvent::BeginDial => {"),
            "the production slice is empty or mis-cut — every assertion below would pass vacuously"
        );

        // The recovery record must be INSIDE the first-frame transition. On the
        // per-frame arm unguarded it would allocate a label set for every frame
        // of the session, which is the `record_ws_lag` defect (~36M
        // allocations/hour) arriving in a second place.
        let first_frame = production
            .split_once("if !self.proven_healthy {")
            .expect("the first-frame transition must exist")
            .1;
        let (first_frame_block, _) = first_frame
            .split_once("\n                }")
            .expect("the first-frame block must close");
        assert!(
            first_frame_block.contains(stringify!(RECONNECT_RECOVERY_MS_METRIC)),
            "the recovery record must sit inside the first-frame transition, never on the \
             per-frame arm"
        );
        assert!(
            first_frame_block.contains("self.outage_started_at.take()"),
            "it must TAKE the stamp — reading it would record one sample per frame"
        );

        // Both swap legs, and the unsubscribe one OUTSIDE its `if let`, so a
        // leg that ELAPSES its budget is still sampled. Recording only the Ok
        // path reports a healthy median while every slow swap vanishes.
        // Count the LEGS, not the symbol: the symbol also appears in a doc
        // comment, and a count that includes prose lets a deleted leg hide
        // behind an added sentence.
        for leg in ["\"leg\" => \"unsubscribe\",", "\"leg\" => \"subscribe\","] {
            assert_eq!(
                production.matches(leg).count(),
                1,
                "exactly one {leg} emit — a missing leg makes the histogram half-blind, and a \
                 duplicated one double-counts every swap"
            );
        }
        let hoist = production
            .find("let unsub_started = tokio::time::Instant::now();")
            .expect("the unsubscribe stamp must exist");
        let if_let = production
            .find("if let Some(drop_this) = swap.unsubscribe {")
            .expect("the unsubscribe leg must exist");
        assert!(
            hoist < if_let,
            "the unsubscribe stamp must be taken BEFORE the `if let`, or the record cannot run \
             on the timeout arm"
        );
    }

    /// Bite-proof for the scan above: the markers it keys on are real, and a
    /// guard that can never fail is worse than no guard because it also
    /// certifies the case is covered.
    #[test]
    fn latency_guard_self_test() {
        let src = include_str!("pool_supervisor.rs");
        for marker in [
            "ConnEvent::BeginDial => {",
            "if !self.proven_healthy {",
            "self.outage_started_at.take()",
            "if let Some(drop_this) = swap.unsubscribe {",
            "let unsub_started = tokio::time::Instant::now();",
        ] {
            assert!(
                src.contains(marker),
                "guard marker {marker:?} no longer appears — the scan above would pass vacuously"
            );
        }
        // And the assertion messages must not themselves satisfy the scan.
        let test_marker = concat!("#[cfg(", "test)]");
        let production = src
            .split_once(&format!("\n{test_marker}"))
            .map_or(src, |(head, _)| head);
        assert!(
            production.len() < src.len(),
            "the production cut must actually remove the test module, or this file's own \
             assertion text counts as production source"
        );
    }

